    .btn-action:hover { background: var(--theme-color); color: #000; box-shadow: 0 0 12px var(--theme-color); transform: translate(-1px, -1px); }
    .btn-action:active { transform: translate(1px, 1px); box-shadow: none; }
    .btn-action:disabled { opacity: 0.4; cursor: not-allowed; transform: none; box-shadow: 2px 2px 0 #000; }
    .btn-action:disabled:hover { background: transparent; color: var(--theme-color); box-shadow: 2px 2px 0 #000; }
    /* 手操模式滑块切换 */
    .ops-switch-wrap { display: flex; align-items: center; gap: 5px; font-size: 9px; color: #94a3b8; cursor: pointer; letter-spacing: 0.5px; }
    .ops-switch-box { position: relative; width: 38px; height: 19px; border-radius: 10px; background: #1e293b; border: 1px solid #334155; display: inline-block; transition: all 0.25s; flex-shrink: 0; }
    .ops-switch-box input { position: absolute; inset: 0; opacity: 0; cursor: pointer; z-index: 5; margin: 0; width: 100%; height: 100%; }
    .ops-switch-box i { position: absolute; top: 2px; left: 2px; width: 13px; height: 13px; border-radius: 50%; background: #64748b; transition: all 0.25s; }
    .ops-switch-box input:checked ~ i { left: 21px; background: var(--acid-green); box-shadow: 0 0 8px var(--acid-green); }
    /* 拖拽悬停吸附预备高亮 */
    .slot-socket.drag-hover {
      border-color: rgba(255, 255, 255, 0.5) !important;
      box-shadow: 0 0 20px rgba(255, 255, 255, 0.25) !important;
    }
    /* 通电装载态：槽位颜色完全对应卡牌颜色（--card-accent） */
    .slot-socket.is-occupied {
      border-color: var(--card-accent) !important;
      box-shadow: 0 14px 30px rgba(0, 0, 0, 0.95), 0 0 25px var(--card-glow), inset 0 0 15px var(--card-glow) !important;
    }
    .slot-socket.is-fixed.is-occupied {
      background: linear-gradient(145deg, #101620 0%, #090e16 50%, #05070c 100%);
    }
    .slot-socket.is-free.is-occupied {
      border-style: dashed !important;
      background: linear-gradient(145deg, #181008 0%, #0d0804 50%, #070402 100%);
    }
    .slot-socket.is-occupied .slot-meta { color: var(--card-accent); }
    .slot-socket.is-occupied .slot-meta b { color: var(--card-accent); }
    .slot-socket.is-occupied .slot-well {
      border-color: var(--card-accent);
      box-shadow: inset 0 4px 12px rgba(0, 0, 0, 0.9), 0 0 15px var(--card-glow);
    }
    .slot-socket.is-occupied .standby-crosshair { opacity: 0; }

    /* 回路卡牌式样 */
    .card-token {
      width: 136px;
      height: 206px;
      position: absolute;
      cursor: grab;
      transform-style: preserve-3d;
      transition: box-shadow 0.2s ease, transform 0.12s ease-out;
      z-index: 10;
    }
    .card-token.dragging {
      cursor: grabbing;
      z-index: 999 !important;
      transform: scale(1.06) rotateZ(-1deg) !important;
      box-shadow: 0 25px 50px rgba(0, 0, 0, 0.95);
    }
    .card-token.selected .card-inner {
      border-color: #fff !important;
      box-shadow: 0 0 0 2px #fff, 0 16px 36px rgba(0,0,0,0.9);
    }
    .card-inner {
      width: 100%;
      height: 100%;
      border-radius: 4px;
      background: var(--card-bg, #0d1118);
      border: 2px solid var(--accent, #334155);
      box-shadow: 0 10px 24px rgba(0,0,0,0.7);
      padding: 10px;
      display: flex;
      flex-direction: column;
      justify-content: space-between;
      position: relative;
      overflow: hidden;
      transition: all 0.2s ease;
    }

    /* ================= 补给卡（照抄 mana_purity_supplies 纯度分级美术） ================= */
    .supply-token {
      width: 150px;
      height: 260px;
      position: absolute;
      cursor: grab;
      z-index: 9;
      transition: box-shadow 0.2s ease, transform 0.12s ease-out;
    }
    .supply-token.dragging {
      cursor: grabbing;
      z-index: 998 !important;
      transform: scale(1.05);
      box-shadow: 0 25px 50px rgba(0, 0, 0, 0.95);
    }
    .supply-shell {
      width: 100%;
      height: 100%;
      background: #090d14;
      border-radius: 5px;
      border: 1.5px solid var(--sup-theme, #334155);
      position: relative;
      overflow: hidden;
      display: flex;
      flex-direction: column;
      justify-content: space-between;
      padding: 9px 8px;
      box-shadow: 0 18px 36px rgba(0,0,0,0.9), 0 0 25px var(--sup-glow, transparent), inset 0 1px 0 rgba(255,255,255,0.25);
    }
    .foil-reflection {
      position: absolute;
      inset: 0;
      pointer-events: none;
      background: linear-gradient(135deg, transparent 30%, rgba(255,255,255,0.08) 48%, var(--sup-glow, transparent) 52%, transparent 60%);
      background-size: 260% 260%;
      mix-blend-mode: overlay;
    }
    .pkg-hole {
      width: 28px;
      height: 6px;
      background: #040609;
      border: 1px solid rgba(255,255,255,0.15);
      border-radius: 3px;
      margin: 0 auto 6px;
    }
    .hazard-stripe {
      position: absolute;
      top: 0; left: 0; right: 0;
      height: 4px;
      background: repeating-linear-gradient(45deg, var(--sup-theme), var(--sup-theme) 8px, #000 8px, #000 16px);
    }
    .supply-header {
      display: flex;
      justify-content: space-between;
      align-items: center;
      font-size: 8px;
      font-weight: 800;
      color: #64748b;
      border-bottom: 1px dashed rgba(255,255,255,0.12);
      padding-bottom: 4px;
    }
    .supply-cat { font-weight: 900; letter-spacing: 0.5px; color: var(--sup-theme); }
    .supply-tierbadge {
      font-size: 7.5px;
