    }
    .supply-name {
      font-family: var(--font-display);
      font-size: 14px;
      font-weight: 900;
      color: #fff;
      line-height: 1.1;
      letter-spacing: -0.3px;
    }
    .sup-uid-n {
      display: inline-block;
