      vertical-align: 1px;
    }
    .supply-quantum {
      margin-top: 4px;
      background: rgba(255,255,255,0.03);
      border-left: 3px solid var(--sup-theme);
      padding: 4px 8px;
      display: flex;
      align-items: baseline;
      justify-content: space-between;
    }
    .supply-purity { font-size: 18px; font-weight: 900; color: #fff; line-height: 1; }
    .supply-purity span { font-size: 11px; color: var(--sup-theme); margin-left: 1px; }
    .supply-add { font-size: 12px; font-weight: 800; color: var(--sup-theme); }
    .supply-art {
      height: 72px;
      background: #05080e;
      border: 1px solid rgba(255,255,255,0.08);
      border-radius: 3px;
      margin: 6px 0;
      display: flex;
      justify-content: center;
      align-items: center;
