    }
    .supply-art::before {
      content: "";
      position: absolute;
      inset: 0;
      background-image: repeating-linear-gradient(0deg, rgba(255,255,255,0.02) 0 1px, transparent 1px 12px),
                        repeating-linear-gradient(90deg, rgba(255,255,255,0.02) 0 1px, transparent 1px 12px);
      pointer-events: none;
    }
    .supply-specs {
      background: rgba(0,0,0,0.45);
      padding: 4px 6px;
      border: 1px solid rgba(255,255,255,0.04);
      border-radius: 2px;
      display: flex;
      flex-direction: column;
      gap: 2px;
      font-size: 7.5px;
    }
    .supply-spec-r { display: flex; justify-content: space-between; color: #94a3b8; }
    .supply-spec-r b { color: #fff; }
    .supply-footer {
      margin-top: 6px;
      display: flex;
      justify-content: space-between;
