    }
    .supply-barcode { height: 14px; opacity: 0.6; }
    .supply-pips { display: flex; gap: 3px; align-items: center; }
    .supply-pip { width: 6px; height: 6px; border: 1px solid var(--sup-theme); background: var(--sup-theme); border-radius: 1px; }
    .supply-pip.empty { background: transparent; opacity: 0.3; }
    .card-token.spent .card-inner {
      border-color: #334155 !important;
      background: #090b0e !important;
      opacity: 0.6;
      filter: grayscale(0.9);
      box-shadow: 0 4px 10px rgba(0,0,0,0.8);
    }
    /* 手操圈选后：卡牌 + 槽位变灰不发光 */
    .card-token.used .card-inner {
      border-color: #334155 !important;
      background: #0a0c10 !important;
      opacity: 0.5;
      filter: grayscale(0.95);
      box-shadow: 0 4px 10px rgba(0,0,0,0.75) !important;
    }
    .slot-socket.used.is-occupied {
      border-color: #334155 !important;
      box-shadow: 0 10px 24px rgba(0,0,0,0.8) !important;
    }
    .slot-socket.used.is-occupied .slot-well {
      border-color: #26303f !important;
      box-shadow: inset 0 4px 12px rgba(0,0,0,0.85) !important;
    }
    .slot-socket.used.is-occupied .slot-meta { color: #4b5a6b !important; }
    .slot-socket.used.is-occupied .slot-meta b { color: #4b5a6b !important; }
    .card-token.spent .spent-overlay-stamp { display: flex; }
    .spent-overlay-stamp {
      display: none;
      position: absolute;
      top: 42%;
      left: 50%;
      transform: translate(-50%, -50%) rotate(-18deg);
      border: 3px solid var(--acid-red);
