      padding: 4px 10px;
      font-family: var(--font-display);
      font-size: 15px;
      font-weight: 900;
      letter-spacing: 2px;
      text-transform: uppercase;
      pointer-events: none;
      z-index: 10;
      background: rgba(10, 5, 8, 0.9);
      white-space: nowrap;
    }
    .token-glare {
      position: absolute;
      inset: 0;
      pointer-events: none;
      background: radial-gradient(circle at 30% 20%, rgba(255,255,255,0.2) 0%, transparent 65%);
      mix-blend-mode: overlay;
    }
    .token-ghost {
      position: absolute;
      top: 36%;
      left: 50%;
      transform: translate(-50%, -50%);
      font-family: var(--font-display);
      font-size: 58px;
      font-weight: 900;
      color: var(--accent);
      opacity: 0.05;
      letter-spacing: -2px;
      pointer-events: none;
    }
    .token-top {
      display: flex;
      justify-content: space-between;
      font-size: 9px;
      font-weight: 800;
      color: var(--accent);
      border-bottom: 1px solid rgba(255,255,255,0.08);
      padding-bottom: 3px;
      z-index: 2;
    }
    .token-name {
      margin-top: 4px;
      border-left: 3px solid var(--accent);
      padding-left: 6px;
      z-index: 2;
    }
    .token-name-1 { font-family: var(--font-display); font-size: 16px; font-weight: 900; color: #fff; line-height: 1.05; }
    .token-name-2 { font-size: 14px; font-weight: 800; color: var(--accent); line-height: 1.05; margin-top: 2px; }
    .token-qtm {
      margin: 4px 0;
      padding: 4px 6px;
      background: rgba(255,255,255,0.03);
      border: 1px solid rgba(255,255,255,0.06);
      z-index: 2;
    }
    .token-val { font-size: 20px; font-weight: 900; color: #fff; line-height: 1; }
    .token-unit { font-size: 12px; color: var(--accent); margin-left: 2px; }
    .token-cost-badge {
      background: var(--accent);
      color: #000;
      font-size: 9.5px;
      font-weight: 900;
      padding: 3px 5px;
      text-align: center;
      letter-spacing: 0.3px;
      z-index: 2;
    }
    .token-switch-bar { margin-top: 5px; display: flex; z-index: 2; }
    .btn-toggle-spent {
      flex: 1;
      background: rgba(255, 255, 255, 0.08);
      border: 1px solid rgba(255, 255, 255, 0.2);
      color: #fff;
      font-size: 9.5px;
      font-weight: 800;
      padding: 4px 2px;
      text-align: center;
      cursor: pointer;
      transition: all 0.2s;
    }
    .btn-toggle-spent:hover { background: #fff; color: #000; }
    .card-token.spent .btn-toggle-spent {
      background: rgba(244, 63, 94, 0.2);
      border-color: var(--acid-red);
      color: var(--acid-red);
    }
    .card-token.spent .btn-toggle-spent:hover { background: var(--acid-red); color: #fff; }

    /* ================= 桌面2：角色桌（全新紧凑高密度 5 族并列矩阵） ================= */
    .char-profile-banner {
      width: 100%;
      max-width: 1480px;
      background: rgba(10, 14, 22, 0.95);
      border: 1px solid rgba(255, 255, 255, 0.1);
      border-radius: 6px;
      padding: 16px 24px;
      box-shadow: 0 15px 40px rgba(0,0,0,0.7);
      display: flex;
      justify-content: space-between;
      align-items: center;
      margin-bottom: 20px;
    }
    .char-bio-block { display: flex; flex-direction: column; gap: 4px; }
    .char-name-title {
      font-family: var(--font-display);
      font-size: 20px;
      font-weight: 900;
      color: #fff;
      display: flex;
      align-items: center;
      gap: 12px;
    }

    .affinity-legend-bar {
      display: flex;
      gap: 14px;
      font-size: 10px;
      align-items: center;
    }
    .leg-badge {
      display: flex;
      align-items: center;
      gap: 6px;
      padding: 4px 10px;
      border-radius: 3px;
      font-weight: 800;
    }
    /* 图例指示发光效果 */
    .leg-badge.primary {
      background: #000;
      border: 1px solid #fff;
      color: #fff;
      box-shadow: 0 0 14px rgba(255, 0, 200, 0.8), 0 0 8px rgba(0, 255, 255, 0.9);
      position: relative;
      overflow: hidden;
    }
    .leg-badge.secondary {
      background: rgba(255, 102, 0, 0.15);
      border: 1px solid var(--acid-orange);
      color: var(--acid-orange);
      box-shadow: 0 0 10px rgba(255, 102, 0, 0.4);
    }
    .leg-badge.none {
      background: rgba(100, 116, 139, 0.1);
      border: 1px solid #334155;
      color: #64748b;
    }

    /* 5 列族群并列矩阵：紧凑消除空间浪费 */
    .affinity-columns-grid {
      width: 100%;
      max-width: 1480px;
      display: grid;
      grid-template-columns: repeat(5, 1fr);
      gap: 16px;
      align-items: start;
    }

    .affinity-family-col {
      background: rgba(12, 16, 24, 0.6);
      border: 1px solid rgba(255, 255, 255, 0.08);
      border-radius: 6px;
      padding: 12px;
      display: flex;
      flex-direction: column;
      gap: 10px;
    }
    .family-col-header {
      border-bottom: 2px solid var(--fam-color, rgba(255,255,255,0.1));
      padding-bottom: 8px;
    }
    .family-col-title {
      font-family: var(--font-display);
      font-size: 14px;
      font-weight: 900;
      color: #fff;
      display: flex;
      justify-content: space-between;
      align-items: center;
    }
    .family-col-sub {
      font-size: 8.5px;
      color: #64748b;
      margin-top: 2px;
      white-space: nowrap;
      overflow: hidden;
      text-overflow: ellipsis;
    }

    .cards-vertical-stack {
      display: flex;
      flex-direction: column;
      gap: 10px;
    }

    /* ================= 亲和卡本体设计 (136px x 152px) ================= */
    .affinity-card {
      width: 100%;
      height: 146px;
      border-radius: 5px;
      background: #090c12;
      padding: 8px 10px;
      display: flex;
      flex-direction: column;
      justify-content: space-between;
      position: relative;
      cursor: pointer;
      transition: transform 0.2s ease, box-shadow 0.25s ease;
      overflow: hidden;
      transform: rotateX(calc(-1 * var(--tilt)));
    }
    .affinity-card:hover {
      transform: rotateX(calc(-1 * var(--tilt))) translateY(-4px) scale(1.02);
      z-index: 20;
    }

    /* -------------------------------------------------------------
       发光机制核心：
       1. 主亲和：彩色流光霓虹 (Multi-color Chromatic Neon Glow)
       2. 次亲和：原本纯色发光 (Solid Branch Glow)
       3. 非亲和：完全不发光 (Zero Glow / Matte Dim)
       ------------------------------------------------------------- */

    /* 1. 主亲和：炫彩霓虹流动边框与多色外发光 */
    .affinity-card.status-primary {
      border: 2px solid transparent;
      background: linear-gradient(#090c12, #090c12) padding-box,
                  linear-gradient(135deg, #ff007f, #00f0ff, #c6ff00, #ff00ea) border-box;
      box-shadow: 0 0 16px rgba(0, 240, 255, 0.45), 
                  0 0 28px rgba(255, 0, 128, 0.35),
                  inset 0 0 12px rgba(198, 255, 0, 0.15);
      animation: neonPulse 3s ease-in-out infinite alternate;
    }
    @keyframes neonPulse {
      0% {
        box-shadow: 0 0 14px rgba(0, 240, 255, 0.5), 0 0 24px rgba(255, 0, 128, 0.4), inset 0 0 10px rgba(198, 255, 0, 0.15);
      }
      100% {
        box-shadow: 0 0 22px rgba(198, 255, 0, 0.6), 0 0 34px rgba(0, 240, 255, 0.5), inset 0 0 16px rgba(255, 0, 200, 0.25);
      }
    }
    .affinity-card.status-primary .aff-level-tag {
      background: linear-gradient(90deg, #00f0ff, #c6ff00);
      color: #000;
      font-weight: 900;
    }

    /* 2. 次亲和：原本分支基调纯色发光 */
    .affinity-card.status-secondary {
      border: 2px solid var(--accent, #ff6600);
      box-shadow: 0 0 14px var(--accent-glow, rgba(255, 102, 0, 0.45)), 
                  inset 0 0 10px rgba(255, 255, 255, 0.03);
    }
    .affinity-card.status-secondary .aff-level-tag {
      background: var(--accent, #ff6600);
      color: #000;
      font-weight: 900;
    }

    /* 3. 非亲和：完全不发光 (暗色消隐) */
    .affinity-card.status-none {
      border: 1px solid #1f2937;
      box-shadow: none !important;
      opacity: 0.5;
    }
    .affinity-card.status-none:hover {
      opacity: 0.85;
      border-color: #475569;
    }
    .affinity-card.status-none .aff-level-tag {
      background: #1f2937;
      color: #64748b;
    }

    /* 卡牌选定态 */
    .affinity-card.selected {
      outline: 2px solid #ffffff;
      outline-offset: 2px;
      opacity: 1 !important;
    }

    .aff-head {
      display: flex;
      justify-content: space-between;
      align-items: center;
      font-size: 8px;
      color: #64748b;
      font-weight: 700;
    }
    .aff-level-tag {
      font-size: 8px;
      font-weight: 800;
      padding: 1px 4px;
      border-radius: 2px;
      letter-spacing: 0.5px;
    }

    /* SVG 几何图腾区 (中置居中) */
    .aff-svg-wrap {
      height: 52px;
      display: flex;
      justify-content: center;
      align-items: center;
      margin: 2px 0;
    }
    .aff-svg-wrap svg {
      width: 48px;
      height: 48px;
      filter: drop-shadow(0 0 6px currentColor);
    }

    .aff-title-box {
      border-left: 2.5px solid var(--accent, #64748b);
      padding-left: 5px;
    }
    .aff-name {
      font-family: var(--font-display);
      font-size: 13.5px;
      font-weight: 900;
      color: #fff;
      line-height: 1.1;
    }
    .aff-sub {
      font-size: 8px;
      color: #718096;
      margin-top: 1px;
      white-space: nowrap;
      overflow: hidden;
      text-overflow: ellipsis;
    }
    .aff-rate-pill {
      font-size: 8px;
      color: #94a3b8;
      background: rgba(255,255,255,0.03);
      padding: 2px 4px;
      text-align: center;
      border: 1px solid rgba(255,255,255,0.05);
      border-radius: 2px;
    }

    /* ================= 屏幕固定侧栏 ================= */
    .screen-sidebar {
      position: fixed;
      top: 48px;
      right: 0;
      width: 380px;
      height: calc(100vh - 48px);
      background: rgba(7, 9, 14, 0.98);
      backdrop-filter: blur(25px);
      border-left: 2px solid #232c3d;
      z-index: 400;
      display: flex;
      flex-direction: column;
      transform: translateX(100%);
      transition: transform 0.3s cubic-bezier(0.16, 1, 0.3, 1);
      box-shadow: -15px 0 40px rgba(0, 0, 0, 0.9);
    }
    .screen-sidebar.open { transform: translateX(0); }

    .sidebar-handle {
      position: absolute;
      top: 50%;
      left: -32px;
      transform: translateY(-50%);
      width: 32px;
      height: 100px;
      background: rgba(7, 9, 14, 0.98);
      border: 2px solid #232c3d;
      border-right: none;
      border-radius: 6px 0 0 6px;
      display: flex;
      flex-direction: column;
      justify-content: center;
      align-items: center;
      cursor: pointer;
      font-size: 10px;
      color: var(--acid-green);
      font-weight: 800;
      letter-spacing: 2px;
      writing-mode: vertical-lr;
      box-shadow: -6px 0 16px rgba(0,0,0,0.6);
      transition: all 0.2s;
    }
    .sidebar-handle:hover { background: var(--acid-green); color: #000; }

    /* 待送审红点（牌库/侧栏/配置桌导航，有剧情获得待送审的牌时点亮） */
    .pending-dot {
      position: absolute;
      top: 4px;
      right: 6px;
      min-width: 15px;
      height: 15px;
      border-radius: 8px;
      background: #f43f5e;
      color: #fff;
      font-size: 9px;
      font-weight: 900;
      line-height: 15px;
      text-align: center;
      padding: 0 4px;
      box-shadow: 0 0 8px rgba(244, 63, 94, 0.9);
      z-index: 30;
      pointer-events: none;
    }
    .sidebar-handle .pending-dot {
      position: absolute;
      top: 6px;
      left: 6px;
      right: auto;
    }

    .sidebar-tabs {
      display: flex;
      border-bottom: 2px solid rgba(255, 255, 255, 0.08);
      background: #0b0e15;
    }
    .tab-btn {
      position: relative;
      flex: 1;
      padding: 14px 10px;
      font-size: 11px;
      font-weight: 800;
      letter-spacing: 1px;
      color: #64748b;
      text-align: center;
      cursor: pointer;
      background: transparent;
      border: none;
      border-bottom: 2px solid transparent;
      transition: all 0.2s;
      font-family: var(--font-mono);
    }
    .tab-btn:hover { color: #fff; }
    .tab-btn.active {
      color: var(--acid-green);
      border-bottom-color: var(--acid-green);
      background: rgba(198, 255, 0, 0.03);
    }

    .tab-content-panel {
      flex: 1;
      overflow-y: auto;
      padding: 18px;
      display: none;
    }
    .tab-content-panel.active {
      display: flex;
      flex-direction: column;
      gap: 14px;
    }

    .repo-card-item {
      padding: 12px;
      background: rgba(13, 17, 24, 0.85);
      border: 1px solid rgba(255, 255, 255, 0.1);
      border-radius: 4px;
      cursor: pointer;
      transition: all 0.2s;
    }
    .repo-card-item:hover { border-color: var(--item-acc, #c6ff00); transform: translateX(-4px); }
    .repo-card-head { display: flex; justify-content: space-between; font-size: 8.5px; color: #64748b; }
    .repo-card-title { font-size: 13px; font-weight: 800; color: #fff; margin: 3px 0; }
    .repo-card-stat { font-size: 9.5px; color: var(--item-acc, #c6ff00); }

    .dos-hero { border-left: 4px solid var(--dos-acc, #c6ff00); padding-left: 12px; }
    .dos-cat { font-size: 9.5px; color: #64748b; }
    .dos-name { font-family: var(--font-display); font-size: 20px; font-weight: 900; color: #fff; margin-top: 4px; }
    .dos-energy { font-size: 24px; font-weight: 800; color: var(--dos-acc, #c6ff00); margin-top: 4px; }
    .dos-anchor { font-size: 11px; color: #94a3b8; }
    .dos-specs { background: rgba(255,255,255,0.03); border: 1px solid rgba(255,255,255,0.06); padding: 12px; }
    .spec-r { display: flex; justify-content: space-between; font-size: 11px; margin-bottom: 6px; }
    .spec-r:last-child { margin-bottom: 0; }
    .spec-r .k { color: #8b99ae; }
    .spec-r .v { color: #fff; font-weight: 600; }
    .dos-banner { background: var(--dos-acc, #c6ff00); color: #000; padding: 8px 12px; font-weight: 800; font-size: 10.5px; }
    .dos-lore { font-size: 11px; line-height: 1.6; color: #94a3b8; border-top: 1px dashed rgba(255,255,255,0.12); padding-top: 12px; }

    .btn-recycle-card {
      margin-top: 10px;
      background: rgba(244, 63, 94, 0.12);
      border: 1px solid var(--acid-red);
      color: var(--acid-red);
      padding: 10px;
      font-size: 11px;
      font-weight: 800;
      text-align: center;
      cursor: pointer;
      letter-spacing: 1px;
      border-radius: 4px;
      transition: all 0.2s;
    }
    .btn-recycle-card:hover {
      background: var(--acid-red);
      color: #fff;
      box-shadow: 0 0 15px rgba(244, 63, 94, 0.4);
    }

    /* ================= 桌面3：自由施法桌 // 临时回路构筑台 ================= */
    .forge-layout { position: absolute; top: 50%; left: 50%; transform: translate(-50%, -50%); display: flex; gap: 28px; align-items: flex-start; }
    .forge-preset-panel { width: 240px; background: rgba(10, 14, 22, 0.94); border: 1px solid rgba(255,255,255,0.1); border-radius: 6px; padding: 18px; display: flex; flex-direction: column; gap: 10px; box-shadow: 0 15px 40px rgba(0,0,0,0.6); }
    .preset-btn { padding: 8px 10px; border: 1px solid #1e293b; background: rgba(255,255,255,0.02); border-radius: 4px; cursor: pointer; text-align: left; transition: all 0.2s; }
    .preset-btn:hover { border-color: var(--acid-green); background: rgba(198,255,0,0.06); }
    .preset-btn.active { border-color: var(--acid-green); background: rgba(198,255,0,0.08); }
    .preset-btn .pn { font-size: 11px; font-weight: 800; color: #fff; }
    .preset-btn .pe { font-size: 8.5px; color: #64748b; }
    .forge-family-panel { width: 240px; background: rgba(10, 14, 22, 0.94); border: 1px solid rgba(255,255,255,0.1); border-radius: 6px; padding: 18px; display: flex; flex-direction: column; gap: 12px; box-shadow: 0 15px 40px rgba(0,0,0,0.6); transform: rotateX(calc(-1 * var(--tilt))); }
    .forge-panel-title { font-family: var(--font-display); font-size: 13px; font-weight: 900; color: #fff; letter-spacing: 1.5px; border-bottom: 1px solid rgba(255,255,255,0.08); padding-bottom: 8px; }
    .fam-switch-item { padding: 12px 14px; border: 1px solid #1e293b; background: rgba(255,255,255,0.02); border-radius: 4px; cursor: pointer; display: flex; justify-content: space-between; align-items: center; transition: all 0.2s; }
    .fam-switch-item:hover { border-color: #64748b; background: rgba(255,255,255,0.04); }
    .fam-switch-item.active { border-color: var(--fcolor, var(--acid-green)); background: rgba(255,255,255,0.06); box-shadow: inset 0 0 12px rgba(255,255,255,0.05), 0 0 10px var(--fglow, rgba(198,255,0,0.3)); }
    .fam-switch-item .fn { font-family: var(--font-display); font-size: 15px; font-weight: 900; color: #fff; }
    .fam-switch-item .fs { font-size: 8.5px; color: #64748b; }
    .forge-tuning-rack { width: 580px; background: rgba(12, 16, 24, 0.94); border: 1px solid rgba(255,255,255,0.1); border-radius: 6px; padding: 24px; display: flex; flex-direction: column; gap: 18px; box-shadow: 0 15px 40px rgba(0,0,0,0.6); transform: rotateX(calc(-1 * var(--tilt))); }
    .rack-header { display: flex; justify-content: space-between; align-items: center; border-bottom: 2px solid var(--cur-fam-color, var(--acid-green)); padding-bottom: 8px; }
    .rack-title { font-family: var(--font-display); font-size: 16px; font-weight: 900; color: #fff; }
    .rack-sub { font-size: 10px; color: #64748b; }
    .ctrl-item { display: flex; flex-direction: column; gap: 6px; }
    .ctrl-label-row { display: flex; justify-content: space-between; font-size: 10px; font-weight: 700; }
    .ctrl-label-row .lbl { color: #8fa0b5; }
    .ctrl-label-row .val { color: var(--cur-fam-color, var(--acid-green)); font-family: var(--font-mono); font-weight: 800; }
    .seg-btn-group { display: flex; gap: 6px; flex-wrap: wrap; }
    .seg-opt-btn { flex: 1; min-width: 90px; background: rgba(255,255,255,0.03); border: 1px solid #1e293b; color: #94a3b8; font-size: 10px; font-weight: 800; padding: 6px 8px; border-radius: 3px; cursor: pointer; text-align: center; font-family: var(--font-mono); transition: all 0.15s; }
    .seg-opt-btn:hover { border-color: #475569; color: #fff; }
    .seg-opt-btn.active { background: var(--cur-fam-color, var(--acid-green)); color: #000; border-color: var(--cur-fam-color, var(--acid-green)); box-shadow: 0 0 10px rgba(0,0,0,0.4); }
    input[type=range].acid-slider { -webkit-appearance: none; width: 100%; height: 6px; background: #1e293b; border-radius: 3px; outline: none; }
    input[type=range].acid-slider::-webkit-slider-thumb { -webkit-appearance: none; width: 16px; height: 16px; border-radius: 2px; background: var(--cur-fam-color, var(--acid-green)); cursor: pointer; box-shadow: 0 0 8px var(--cur-fam-color, var(--acid-green)); }
    .forge-telemetry-hud { width: 440px; background: rgba(8, 10, 15, 0.96); border: 2px solid #232c3d; border-radius: 6px; padding: 22px; display: flex; flex-direction: column; gap: 16px; box-shadow: 0 20px 50px rgba(0,0,0,0.8); transform: rotateX(calc(-1 * var(--tilt))); }
    .tele-header { display: flex; justify-content: space-between; align-items: center; border-bottom: 1px solid rgba(255,255,255,0.08); padding-bottom: 8px; }
    .tele-title { font-family: var(--font-display); font-size: 14px; font-weight: 900; color: #fff; }
    .gate-badge { font-size: 9.5px; font-weight: 900; padding: 2px 6px; border-radius: 2px; }
    .gate-badge.main { background: var(--acid-green); color: #000; }
    .gate-badge.mid { background: var(--acid-orange); color: #000; }
    .gate-badge.far { background: var(--acid-red); color: #fff; }
    .tele-quantum-box { background: rgba(255,255,255,0.03); border: 1px solid rgba(255,255,255,0.08); padding: 12px; display: flex; flex-direction: column; gap: 4px; }
    .tele-q-lbl { font-size: 8.5px; color: #64748b; letter-spacing: 1px; }
    .tele-q-num { font-family: var(--font-mono); font-size: 30px; font-weight: 900; color: #fff; line-height: 1; }
    .tele-q-anchor { font-size: 11px; color: var(--acid-green); font-weight: 700; margin-top: 4px; }
    .tele-grid-stats { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; }
    .stat-card-mini { background: rgba(255,255,255,0.02); border: 1px solid rgba(255,255,255,0.06); padding: 8px 10px; }
    .stat-card-mini .k { font-size: 8.5px; color: #64748b; }
    .stat-card-mini .v { font-size: 14px; font-weight: 800; color: #fff; margin-top: 2px; }
    .tuned-alert-box { display: none; padding: 8px 10px; border: 1px solid var(--acid-green); background: rgba(198, 255, 0, 0.08); color: var(--acid-green); font-size: 9.5px; font-weight: 800; }
    .tuned-alert-box.active { display: block; }
    .chips-flow { display: flex; flex-direction: column; gap: 4px; max-height: 140px; overflow-y: auto; padding-right: 2px; scrollbar-width: thin; scrollbar-color: rgba(100,116,139,0.6) transparent; }
    .chips-flow::-webkit-scrollbar { width: 5px; }
    .chips-flow::-webkit-scrollbar-track { background: rgba(255,255,255,0.03); border-radius: 3px; }
    .chips-flow::-webkit-scrollbar-thumb { background: rgba(100,116,139,0.5); border-radius: 3px; }
    .chips-flow::-webkit-scrollbar-thumb:hover { background: var(--acid-green); }
    .chip-line { font-size: 9px; padding: 3px 6px; border-radius: 2px; background: rgba(255,255,255,0.03); color: #94a3b8; border-left: 2px solid #64748b; }
    .chip-line.r { border-color: var(--acid-red); color: #fca5a5; }
    .chip-line.o { border-color: var(--acid-orange); color: #fdba74; }
    .chip-line.y { border-color: var(--acid-yellow); color: #fde047; }
    .intent-input-wrap { display: flex; flex-direction: column; gap: 6px; }
    .intent-textarea { width: 100%; height: 48px; background: #0d121c; border: 1px solid #1e293b; color: #fff; font-family: var(--font-mono); font-size: 11px; padding: 8px; resize: none; outline: none; }
    .intent-textarea:focus { border-color: var(--acid-green); }
    .forge-action-btns { display: flex; gap: 10px; }
    .btn-forge-submit { flex: 1; padding: 10px; font-family: var(--font-display); font-size: 12px; font-weight: 900; cursor: pointer; border: none; border-radius: 2px; transition: all 0.2s; }
    .btn-forge-submit.save { background: rgba(255,255,255,0.06); border: 1px solid rgba(255,255,255,0.2); color: #fff; }
    .btn-forge-submit.save:hover { background: #fff; color: #000; }
    .btn-forge-submit.cast { background: var(--acid-green); color: #000; box-shadow: 0 0 15px rgba(198, 255, 0, 0.4); }
    .btn-forge-submit.cast:hover { box-shadow: 0 0 25px rgba(198, 255, 0, 0.8); }

    /* 主亲和卡牌全彩：图案 / 左上角族名 / 左侧竖线 全部上色（叠加在外壳霓虹之上） */
    .affinity-card.status-primary .aff-head { color: var(--accent); }
    .affinity-card.status-primary .aff-svg-wrap svg { color: var(--accent); filter: drop-shadow(0 0 8px var(--accent-glow)); }
    .affinity-card.status-primary .aff-title-box { border-left-color: var(--accent); }
    .affinity-card.status-primary .aff-sub { color: var(--accent); opacity: 0.9; }

    /* 桌面 3 画布大小 */
    #surfaceDesk3 {
      width: 3200px;
      height: 2200px;
    }

    /* 顶栏精神力能级显示 */
    .top-mental-dialer {
      display: flex;
      flex-direction: column;
      align-items: flex-end;
      justify-content: center;
      padding: 0 14px;
      border-left: 1px solid rgba(255,255,255,0.08);
    }
    .mental-label-group {
      display: flex;
      flex-direction: column;
      gap: 2px;
      font-size: 9px;
      align-items: flex-end;
    }
  </style>
</head>
<body>
<div id="gdesk">

<!-- 0. 屏幕最顶端：工作桌切换导航条 -->
<nav class="top-desk-switcher">
  <div class="brand-group">
    <span class="brand-txt">GRADIENT ZONE</span>
    <span class="brand-badge">DESK MATRIX</span>
  </div>

  <div class="table-nav-tabs">
    <button class="nav-tab-btn active" id="btnNavDesk1" data-target="desk1">
      <span class="tab-num">[1]</span>
      <span>回路配置桌</span>
      <span class="pending-dot" id="dotDesk1" style="display:none"></span>
    </button>
    <button class="nav-tab-btn" id="btnNavDesk2" data-target="desk2">
      <span class="tab-num">[2]</span>
      <span>角色桌 // 亲和光谱</span>
    </button>
    <button class="nav-tab-btn" id="btnNavDesk3" data-target="desk3">
      <span class="tab-num">[3]</span>
      <span>自由施法桌 // 临时回路构筑</span>
    </button>
  </div>

  <div class="top-mental-dialer">
    <div class="mental-label-group">
      <span style="color:#64748b;">精神力能级 // MENTAL LIGHT</span>
      <span style="font-weight:900; color:var(--light-primary);" id="mentalFaderVal">--</span>
    </div>
  </div>

  <div class="top-status-indicator" id="topActorSummary">
    <!-- 动态载入角色概览 -->
  </div>
</nav>

<div class="hud-controls-hint">
  <span>[ <em>顶部切换工作台</em> ]</span>
  <span>[ <em>滚轮</em> 缩放桌台景深 ]</span>
  <span>[ <em>三张桌面均支持自由抓取拖拽平移与滚轮缩放</em> ]</span>
  <span>[ <em>点击任意卡牌</em> 侧栏展开详细档案 ]</span>
  <span>[ <em>构筑台参数</em> 由引擎纯函数刚性报价 ]</span>
</div>

<!-- 屏幕固定右侧栏 -->
<aside class="screen-sidebar" id="screenSidebar">
  <div class="sidebar-handle" id="sidebarHandle">侧栏 // HUD<span class="pending-dot" id="dotHandle" style="display:none"></span></div>

  <div class="sidebar-tabs">
    <button class="tab-btn" id="tabBtnRepo" data-tab="tabRepo">回路牌库<span class="pending-dot" id="dotRepo" style="display:none"></span></button>
    <button class="tab-btn" id="tabBtnSupply" data-tab="tabSupply">补给品库</button>
    <button class="tab-btn active" id="tabBtnDetail" data-tab="tabDetail">卡牌档案显示</button>
  </div>

  <div class="tab-content-panel" id="tabRepo">
    <div style="font-size:10px; color:#64748b; letter-spacing:1px; margin-bottom:6px;">
      RESERVE CIRCUITS // 备选回路库（自由回路）
    </div>
    <div id="repoListContainer" style="display:flex; flex-direction:column; gap:10px;"></div>
  </div>

  <div class="tab-content-panel" id="tabSupply">
    <div style="font-size:10px; color:#64748b; letter-spacing:1px; margin-bottom:6px;">
      SUPPLY DECK // 补给品库（点卡放到回路配置桌）
    </div>
    <div id="supplyListContainer" style="display:flex; flex-direction:column; gap:10px;"></div>
  </div>

  <div class="tab-content-panel active" id="tabDetail">
    <div id="detailContainer">
      <div style="text-align:center; padding:60px 20px; color:#475569; font-size:11px;">
        [ 未选定卡牌 ]<br>点击桌面上任意回路卡或亲和卡，在此处显示详细参数
      </div>
    </div>
  </div>
</aside>

<!-- ================= 视口 1：回路配置桌 ================= -->
<div class="tabletop-viewport active" id="viewportDesk1">
  <div class="table-surface" id="surfaceDesk1">

    <div class="desk1-center">
    <div class="desk-monitors">
      <div class="dial-block">
        <span class="dial-title">身体状态 // VITALS</span>
        <span class="dial-val" id="valBody">--</span>
      </div>
      <div class="dial-block">
        <span class="dial-title">能量 / 精神 // RES</span>
        <span class="dial-val" style="color:var(--acid-green);" id="valRes">--</span>
      </div>
      <div class="dial-block">
        <span class="dial-title">剧情锚点 // TIME</span>
        <span class="dial-val" id="valTime">--</span>
      </div>
      <div class="dial-block">
        <span class="dial-title">脑神经负荷 // BURDEN</span>
        <span class="dial-val" id="valBurden">--</span>
      </div>
      <div class="dial-block" style="justify-content:center;">
        <button class="combat-switch" id="btnCombatToggle">非战斗 [槽位自由]</button>
      </div>
    </div>

    <div class="slot-matrix-grid" id="slotMatrixGrid">
      <div class="matrix-header">
        <span class="matrix-title">固定回路托盘 // 槽位随精神上限（固定 10点1槽 · 自由 30点1槽）</span>
        <div class="matrix-ctrls">
          <label class="ops-switch-wrap">
            <span>非手操</span>
            <span class="ops-switch-box"><input type="checkbox" id="chkManualOps"><i></i></span>
            <span>手操</span>
          </label>
          <button class="btn-slot-mod" id="btnConfirmOps" style="border-color:#334155; color:#64748b; opacity:0.5;" disabled>确认使用（圈选槽位）</button>
          <button class="btn-slot-mod" id="btnManualRecalc" style="border-color:#38bdf8; color:#38bdf8;" title="按脚本重算全部回路的过载率 / 过载风险">⟳ 手动更新过载</button>
        </div>
      </div>
      <div class="slots-container" id="slotsContainer"></div>
    </div>

    <div class="recycle-row">
    <div class="review-dock" id="reviewDock">
      <div class="review-dock-head">
        <span class="matrix-title">法案审核台 // 送审槽（与固定/自由槽隔离 · 仅接受「待送审」回路 · 送审完毕自动回牌库）</span>
      </div>
      <div class="review-dock-body">
        <div class="slot-socket is-review" id="socket_review">
          <div class="slot-meta"><span>REV 01 [审核]</span><b>JUDGE GATE</b></div>
          <div class="slot-well"><div class="standby-crosshair"><div class="cross-circle">⚖</div><span>拖入待送审回路 → 点下方送审</span></div></div>
        </div>
        <button class="review-btn" id="btnReviewDock" disabled>⚖ 送审（送审槽为空）</button>
      </div>
    </div>

    <div class="delete-dock" id="deleteDock">
      <div class="review-dock-head">
        <span class="matrix-title" style="color:#f87171;">销毁台 // 删除槽（所有回路均可删除 · 确认后永久销毁）</span>
      </div>
      <div class="review-dock-body">
        <div class="slot-socket is-delete" id="socket_delete">
          <div class="slot-meta"><span>DEL 01 [销毁]</span><b>SCRAP</b></div>
          <div class="slot-well"><div class="standby-crosshair"><div class="cross-circle">✕</div><span>拖入要删除的回路 → 点下方删除</span></div></div>
        </div>
        <button class="delete-btn" id="btnDeleteDock" disabled>✕ 删除（删除槽为空）</button>
      </div>
    </div>

    <div class="supply-rack" id="supplyRack">
      <div class="feed-hud">
        <div class="hud-col c-cyan"><span class="hud-label">ENERGY / 当前能量</span><b id="hudEnergy">-- / -- kJ</b></div>
        <div class="hud-col c-mag"><span class="hud-label">MENTAL / 当前精神</span><b id="hudMind">-- / -- 点</b></div>
      </div>
      <div class="feed-row">
        <div class="module-card mod-crystal">
          <div class="module-header"><span class="module-name">CRYSTAL HARVEST</span><span class="module-id">SYS_01 晶体</span></div>
          <div class="module-readout"><span class="readout-tag">库存总能量</span><div class="readout-digits"><span id="txtEnergy">0</span><em>kJ</em></div></div>
          <div class="slider-box">
            <div class="slider-meta"><span>能量配额标尺</span><b id="lblEnergy">0 kJ</b></div>
            <input type="range" class="compact-slider" id="crystalSlider" min="0" max="1" step="1" value="0" disabled>
          </div>
          <button class="btn-action" id="btnCrystalUse" disabled>COMMIT ENERGY</button>
        </div>
        <div class="module-card mod-liquid">
          <div class="module-header"><span class="module-name">MENTAL PERFUSION</span><span class="module-id">SYS_02 导液</span></div>
