  function loadFromSave() {
    g = readChat();
    if (!g) return false;

    // 主角横幅
    var zhu = g.主角;
    isCombat = !!zhu.战斗中;   // 从存档同步战斗状态（否则槽位锁/战备开关与存档脱节）
    CURRENT_ACTOR.name = '施法者';
    CURRENT_ACTOR.title = (zhu.战斗中 ? '战斗中' : '非战斗') + ' · ' + (zhu.身体状态 || '正常');
    CURRENT_ACTOR.department = '能量 ' + Math.round(zhu.能量kJ.当前) + '/' + zhu.能量kJ.上限 + 'kJ';
    CURRENT_ACTOR.truth = '精神 ' + Math.round(zhu.精神点.当前) + '/' + zhu.精神点.上限;

    // 亲和映射：主分支 → primary；次分支 → secondary；其余 none
    CURRENT_ACTOR.affinityMap = {};
    var aff = affinityOf(g);
    aff.main.forEach(function (m) { CURRENT_ACTOR.affinityMap[affKey(m.族, m.分支)] = 'primary'; });
    aff.subs.forEach(function (s2) { var k = affKey(s2.族, s2.分支); if (!CURRENT_ACTOR.affinityMap[k]) CURRENT_ACTOR.affinityMap[k] = 'secondary'; });

    // 槽位容量：固定槽 = clamp(精神上限/10, 2, 8)；自由槽 = clamp(精神上限/30, 1, 4)
    var mindMax = (g.主角.精神点 && g.主角.精神点.上限) || 30;
    FIXED_CAP = Math.max(2, Math.min(8, Math.floor(mindMax / 10)));
    FREE_CAP = Math.max(1, Math.min(4, Math.floor(mindMax / 30)));

    // 回路卡：槽位（按容量截断）+ 回路库
    ON_DESK_CARDS = [];
    var slotIndex = 0;
    (g.槽位.固定槽 || []).slice(0, FIXED_CAP).forEach(function (id) {
      if (!id) { slotIndex++; return; }
      var c = circuitById(g, id);
      if (c) { ON_DESK_CARDS.push(toDeskCard(c, 'fixed', slotIndex)); }
      slotIndex++;
    });
    (g.槽位.自由槽 || []).slice(0, FREE_CAP).forEach(function (id) {
      if (!id) { slotIndex++; return; }
      var c = circuitById(g, id);
      if (c) { ON_DESK_CARDS.push(toDeskCard(c, 'free', slotIndex)); }
      slotIndex++;
    });

    // 送审槽中的回路（审核暂存；送审完毕由 clearReviewDockAndRefresh 清标记自动回牌库）
    g.回路库.forEach(function (c) {
      if (!c.送审槽) return;
      var d = toDeskCard(c, 'review', null);
      d.reviewSlot = true;
      d.x = REVIEW_ANCHOR.x; d.y = REVIEW_ANCHOR.y;
      ON_DESK_CARDS.push(d);
    });

    // 删除槽中的回路（销毁暂存；点删除确认后永久移除）
    g.回路库.forEach(function (c) {
      if (!c.待删槽) return;
      var d = toDeskCard(c, 'delete', null);
      d.deleteSlot = true;
      d.x = DELETE_ANCHOR.x; d.y = DELETE_ANCHOR.y;
      ON_DESK_CARDS.push(d);
    });

    // 自由放置的卡（有桌面位置、未装槽）→ 也显示在桌上
    var mountedIds = new Set(ON_DESK_CARDS.map(function (c) { return c.id; }));
    g.回路库.forEach(function (c) {
      if (!c.桌面位置) return;
      if (mountedIds.has(c.id)) return;
      ON_DESK_CARDS.push(toDeskCard(c, c.type, null));
    });

    // 备选牌库：待送审且未上桌的回路 + 未装槽、未上桌的自由回路
    var mounted = new Set(ON_DESK_CARDS.map(function (c) { return c.id; }));
    REPO_CARDS = g.回路库.filter(function (c) {
      if (c.送审槽) return false;                        // 正在送审槽中的不进牌库（送审完自动回）
      if (c.待删槽) return false;                        // 正在删除槽中的不进牌库（确认删除或拖回）
      if (c.桌面位置) return false;                       // 已自由放到桌上的不进牌库
      if (c.审核状态 === '待送审') return true;           // 待送审（未上桌）进牌库等送审
      return !mounted.has(c.id);                          // 未装槽（fixed + free 都进牌库，回收后可见）
    }).map(function (c) { return toDeskCard(c, c.type, null); });

    updatePendingDots();
    loadSupplies();
    return true;
  }

