      branches: [
        { id: 'aff_perce_五感延伸', name: '五感延伸', desc: '超声多普勒、视神经微动全景成像', svg: '<svg viewBox="0 0 64 64" fill="none" stroke="currentColor" stroke-width="2.2"><path d="M8 32 C18 16 46 16 56 32 C46 48 18 48 8 32 Z"/><circle cx="32" cy="32" r="8"/><circle cx="32" cy="32" r="3" fill="currentColor"/></svg>', lore: '只读不写，闭眼听风即可在大脑绘制三维实时声场。' },
