        { id: 'aff_perce_信息伪造', name: '信息伪造', desc: '幻术相位投射与虚假多普勒频移', svg: '<svg viewBox="0 0 64 64" fill="none" stroke="currentColor" stroke-width="2.2"><polygon points="32,8 54,52 10,52"/><polygon points="32,22 44,46 20,46" stroke-dasharray="2,2"/></svg>', lore: '相位伪造与声学欺骗，情报与谍战的核心手段。' }
