  /* ═══════════════════ 桌面1：槽位 + 回路卡渲染 ═══════════════════ */
  var slotsContainer = $('#slotsContainer');
  var surfaceDesk1 = $('#surfaceDesk1');
  var SOCKET_COORDS = [];  // 槽位锚点（写死）：进槽卡的 left/top 固定用这份坐标；zoom/pan 不影响，仅布局变化时重算
  var REVIEW_ANCHOR = { x: 0, y: 0 };   // 送审槽锚点（写死，同槽位锚点口径）
  var DELETE_ANCHOR = { x: 0, y: 0 };   // 删除槽锚点（写死，同槽位锚点口径）
  var btnReviewDock = $('#btnReviewDock');
  var btnDeleteDock = $('#btnDeleteDock');

  /* ── 手操（桌1）：手操模式切换 + 槽位「使用」圈选 + 确认扣费（每轮一个回路一次） ── */
  var manualOps = false;        // 手操模式开关
  var opsUsedSet = {};          // 本轮已圈选的回路 id（每轮一个回路一次）
  var chkManualOps = $('#chkManualOps');
  var btnConfirmOps = $('#btnConfirmOps');

  function updateSlotUseButtons() {
    for (var i = 0; i < slotsContainer.children.length; i++) {
      var btn = document.getElementById('useBtn_' + i);
      if (!btn) continue;
      var c = ON_DESK_CARDS.find(function (x) { return x.slotIndex === i; });
      var used = c ? !!opsUsedSet[c.id] : false;
      // 使用后变灰：圈选的卡牌 + 槽位都不发光
      if (c) {
        var cardEl = document.querySelector('#surfaceDesk1 .card-token[data-id="' + c.id + '"]');
        if (cardEl) cardEl.classList.toggle('used', used);
        var sock = document.getElementById('socket_' + i);
        if (sock) sock.classList.toggle('used', used);
      }
      if (manualOps && c) {   // 手操模式 + 该槽有卡：可圈选（送审在确认时再拦）
        btn.disabled = false;
        btn.textContent = used ? '● 已用' : '○ 使用';
        btn.style.opacity = used ? '0.55' : '1';
        btn.style.borderColor = used ? '#c6ff00' : '';
      } else if (c) {
        btn.disabled = true;
        btn.textContent = '○ 使用';
        btn.style.opacity = '0.35';
      } else {
        btn.disabled = true;
        btn.textContent = '—';
        btn.style.opacity = '0.2';
      }
    }
  }

  chkManualOps.addEventListener('change', function () {
    manualOps = chkManualOps.checked;
    if (!manualOps) opsUsedSet = {};
    btnConfirmOps.disabled = !manualOps;
    btnConfirmOps.style.opacity = manualOps ? '1' : '0.5';
    btnConfirmOps.style.borderColor = manualOps ? '#c6ff00' : '#334155';
    btnConfirmOps.style.color = manualOps ? '#c6ff00' : '#64748b';
    updateSlotUseButtons();
  });

  slotsContainer.addEventListener('click', function (e) {
    var btn = e.target;
    if (!btn.classList || !btn.classList.contains('slot-use-btn')) return;
    if (!manualOps || btn.disabled) return;
    var slotIdx = Number(btn.dataset.slot);
    var c = ON_DESK_CARDS.find(function (x) { return x.slotIndex === slotIdx; });
    if (!c) return;
    if (opsUsedSet[c.id]) delete opsUsedSet[c.id];
    else opsUsedSet[c.id] = true;
    updateSlotUseButtons();
  });

  btnConfirmOps.addEventListener('click', function () {
    if (!manualOps) return;
    var ids = Object.keys(opsUsedSet);
    if (!ids.length) { alert('手操模式：先点槽位下的「○ 使用」圈选回路（每轮一个回路一次）'); return; }
    writeGame(function (gg) {
      var ctx = {
        aff: affinityOf(gg),
        scene: { wind: gg.场景.风力档, mat: gg.场景.可塑无机物kJ, water: gg.场景.水体在场 },
        char: { burstKW: gg.主角.爆发线kW, sustainKW: gg.主角.持续线kW, speed: 1, eCur: gg.主角.能量kJ.当前, mCur: gg.主角.精神点.当前, mMax: gg.主角.精神点.上限, body: gg.主角.身体状态 },
        tuned: tunedList(gg)
      };
      var names = [];
      ids.forEach(function (id) {
        var c = gg.回路库.find(function (x) { return x.id === id; });
        if (!c || !可用(c)) return;
        var q = E.quote({ fam: c.famKey, e: c.注册e || 0, c: c.参数向量 }, ctx);
        // 挂待扣单（不当场扣，回合末 settle ⑥a 统一扣；ref=回路 id，数据AI 报"本轮使用回路"靠 id 对上）
        var pend = {
          ref: c.id,
          名称: c.名称 + '（手操）',
          bill: q.bill, mind: q.mind, tell: q.tell, risk: q.risk,
          锚点: E.anchorOf(q.E_out), order: E.compileOrder(q), famKey: c.famKey
        };
        gg.待扣单.push(pend);
        names.push(c.名称);
      });
      gg['操作表'] = { manual: false, circuits: [], counts: [] };
    });
    opsUsedSet = {};
    chkManualOps.checked = false;
    manualOps = false;
    btnConfirmOps.disabled = true;
    btnConfirmOps.style.opacity = '0.5';
    btnConfirmOps.style.borderColor = '#334155';
    btnConfirmOps.style.color = '#64748b';
    loadFromSave(); renderDesktopCards(); renderDesktopSupplyCards(); renderRepoList(); renderMonitors(); renderSupplyList();
    alert('手操确认：' + (names.join('，') || '无') + ' 已挂入待扣单（回合末 settle ⑥a 统一扣费；数据AI 只计次不重复扣）');
  });

  function buildSlots() {
    slotsContainer.innerHTML = '';
    var total = FIXED_CAP + FREE_CAP;
    for (var i = 0; i < total; i++) {
      var socket = document.createElement('div');
      socket.className = 'slot-socket ' + (i < FIXED_CAP ? 'is-fixed' : 'is-free');
      socket.id = 'socket_' + i;
      var isFree = i >= FIXED_CAP;
      socket.innerHTML =
        '<div class="slot-meta"><span>' + (isFree ? 'BUS ' : 'BAY ') + (i < 9 ? '0' + (i + 1) : (i + 1)) + ' [' + (isFree ? '自由' : '固定') + ']</span><b>' + (isFree ? 'VOLATILE' : 'IMMUTABLE') + '</b></div>' +
        '<div class="slot-well">' +
          '<div class="standby-crosshair"><div class="cross-circle">' + (isFree ? '⇲' : '+') + '</div><span>' + (isFree ? '临时外挂母线' : '待推入导轨') + '</span></div>' +
        '</div>' +
        '<button class="slot-use-btn" id="useBtn_' + i + '" data-slot="' + i + '" disabled>○ 使用</button>';
      slotsContainer.appendChild(socket);
    }
    updateSlotUseButtons();
  }

  var CARD_W = 136, CARD_H = 206;   // 卡牌尺寸（贴合：卡在 slot-well 内居中）
  // 槽位锚点（写死）：只在初始化/布局变化时算一次，之后进槽的卡一律用这份整数坐标。
  // 不随每次渲染重算 → 缩放/平移后再重渲染卡片位置不变（修掉「缩放后漂移 / 向右下偏」）。
  function computeSocketAnchors() {
    SOCKET_COORDS.length = 0;
    var surfaceRect = surfaceDesk1.getBoundingClientRect();
    for (var i = 0; i < slotsContainer.children.length; i++) {
      var sock = document.getElementById('socket_' + i);
      if (!sock) continue;
      var well = sock.querySelector('.slot-well');
      var r = well ? well.getBoundingClientRect() : sock.getBoundingClientRect();
      SOCKET_COORDS.push({
        x: Math.round((r.left - surfaceRect.left) / zoom1 + (r.width / zoom1 - CARD_W) / 2),
        y: Math.round((r.top - surfaceRect.top) / zoom1 + (r.height / zoom1 - CARD_H) / 2),
        index: i
      });
    }
    // 送审槽锚点（独立 socket，不进 numeric 索引；与槽位锚点同口径写死）
    var revSock = document.getElementById('socket_review');
    if (revSock) {
      var revWell = revSock.querySelector('.slot-well');
      var rr = revWell ? revWell.getBoundingClientRect() : revSock.getBoundingClientRect();
      REVIEW_ANCHOR.x = Math.round((rr.left - surfaceRect.left) / zoom1 + (rr.width / zoom1 - CARD_W) / 2);
      REVIEW_ANCHOR.y = Math.round((rr.top - surfaceRect.top) / zoom1 + (rr.height / zoom1 - CARD_H) / 2);
    }
    // 删除槽锚点（独立 socket，不进 numeric 索引；与槽位锚点同口径写死）
    var delSock = document.getElementById('socket_delete');
    if (delSock) {
      var delWell = delSock.querySelector('.slot-well');
      var dr = delWell ? delWell.getBoundingClientRect() : delSock.getBoundingClientRect();
      DELETE_ANCHOR.x = Math.round((dr.left - surfaceRect.left) / zoom1 + (dr.width / zoom1 - CARD_W) / 2);
      DELETE_ANCHOR.y = Math.round((dr.top - surfaceRect.top) / zoom1 + (dr.height / zoom1 - CARD_H) / 2);
    }
    // 补给匣已移至送审/销毁之间（recycle-row 流内布局），无需锚点定位
  }

  function renderDesktopCards() {
    document.querySelectorAll('#surfaceDesk1 .card-token').forEach(function (el) { el.remove(); });
    // 清除所有槽位的装载态（变色复位为休眠）
    document.querySelectorAll('#slotsContainer .slot-socket').forEach(function (el) {
      el.classList.remove('is-occupied');
      el.style.removeProperty('--card-accent');
      el.style.removeProperty('--card-glow');
    });
    var revSockEl = document.getElementById('socket_review');
    if (revSockEl) {
      revSockEl.classList.remove('is-occupied');
      revSockEl.style.removeProperty('--card-accent');
      revSockEl.style.removeProperty('--card-glow');
    }
    var delSockEl = document.getElementById('socket_delete');
    if (delSockEl) {
      delSockEl.classList.remove('is-occupied');
      delSockEl.style.removeProperty('--card-accent');
      delSockEl.style.removeProperty('--card-glow');
    }
    if (!SOCKET_COORDS.length) computeSocketAnchors();   // 锚点兜底（正常由 init/resize 算好，不随渲染重算）
    ON_DESK_CARDS.forEach(function (c) {
      if (c.reviewSlot) {
        c.x = REVIEW_ANCHOR.x; c.y = REVIEW_ANCHOR.y;
        if (revSockEl) {
          revSockEl.classList.add('is-occupied');
          revSockEl.style.setProperty('--card-accent', c.accent);
          revSockEl.style.setProperty('--card-glow', c.accent);
        }
      } else if (c.deleteSlot) {
        c.x = DELETE_ANCHOR.x; c.y = DELETE_ANCHOR.y;
        if (delSockEl) {
          delSockEl.classList.add('is-occupied');
          delSockEl.style.setProperty('--card-accent', c.accent);
          delSockEl.style.setProperty('--card-glow', c.accent);
        }
      } else if (c.slotIndex !== null && c.slotIndex !== undefined && c.slotIndex < SOCKET_COORDS.length) {
        c.x = SOCKET_COORDS[c.slotIndex].x; c.y = SOCKET_COORDS[c.slotIndex].y;
        // 槽位通电装载：点亮为卡牌颜色（参考 gemini-code 槽位联动）
        var sock = document.getElementById('socket_' + c.slotIndex);
        if (sock) {
          sock.classList.add('is-occupied');
          sock.style.setProperty('--card-accent', c.accent);
          sock.style.setProperty('--card-glow', c.accent);
        }
      }
      var cardEl = document.createElement('div');
      cardEl.className = 'card-token ' + (c.spent ? 'spent' : '') + (selectedEntity && selectedEntity.id === c.id ? ' selected' : '');
      cardEl.style.setProperty('--accent', c.accent);
      cardEl.style.left = c.x + 'px'; cardEl.style.top = c.y + 'px';
      cardEl.dataset.id = c.id;
      var slotDisplay = (c.slotIndex !== null && c.slotIndex !== undefined) ? '0' + (c.slotIndex + 1) : (c.reviewSlot ? 'REV' : (c.deleteSlot ? 'DEL' : 'FREE'));
      cardEl.innerHTML =
        '<div class="card-inner"><div class="spent-overlay-stamp">已使用</div><div class="token-glare"></div>' +
        '<div class="token-ghost">' + c.ghost + '</div>' +
        '<div><div class="token-top"><span>' + slotDisplay + '</span><span>' + c.category + '</span></div>' +
        '<div class="token-name"><div class="token-name-1">' + c.name.slice(0, 3) + '</div><div class="token-name-2">' + c.name.slice(3) + '</div></div></div>' +
        '<div class="token-qtm"><div class="token-val">' + c.energy + '<span class="token-unit">' + c.unit + '</span></div></div>' +
        '<div><div class="token-cost-badge">' + c.costBadge + '</div></div></div>';
      bindFreeDragAndSnap(cardEl, c);
      surfaceDesk1.appendChild(cardEl);
    });
    updateSlotUseButtons();
    updateReviewDock();
    updateDeleteDock();
  }

  function bindFreeDragAndSnap(cardEl, cardData) {
    var isMouseDown = false, hasMoved = false, startX = 0, startY = 0, initX = 0, initY = 0;
    cardEl.addEventListener('mousedown', function (e) {
      isMouseDown = true; hasMoved = false;
      startX = e.clientX; startY = e.clientY; initX = cardData.x; initY = cardData.y;
      e.stopPropagation();
    });
    window.addEventListener('mousemove', function (e) {
      if (!isMouseDown) return;
      var dist = Math.hypot(e.clientX - startX, e.clientY - startY);
      if (dist > 6) {
        hasMoved = true;
        cardEl.classList.add('dragging');
        cardData.x = initX + (e.clientX - startX) / zoom1;
        cardData.y = initY + (e.clientY - startY) / zoom1;
        cardEl.style.left = cardData.x + 'px'; cardEl.style.top = cardData.y + 'px';
        checkSocketHover(cardEl);
      }
    });
    window.addEventListener('mouseup', function () {
      if (!isMouseDown) return;
      isMouseDown = false; cardEl.classList.remove('dragging'); clearSocketHighlights();
      if (hasMoved) {
        var hitIndex = getOverlappingSocket(cardEl);
        if (hitIndex === 'review') {
          // 送审槽：仅接受「待送审」回路；进槽写瞬态标记 送审槽=true，送审完毕自动回牌库
          var revC = circuitById(g, cardData.id);
          if (!revC || revC.审核状态 !== '待送审') {
            alert('送审槽只接受「待送审」回路（已通过/免审的回路无需送审）。');
          } else {
            writeGame(function (gg) {
              var fixedLen = FIXED_CAP;
              var src = (cardData.slotIndex !== null && cardData.slotIndex < fixedLen) ? { arr: gg.槽位.固定槽, idx: cardData.slotIndex } : { arr: gg.槽位.自由槽, idx: cardData.slotIndex - fixedLen };
              if (cardData.slotIndex !== null && src.idx >= 0 && src.idx < src.arr.length) src.arr[src.idx] = null;
              var cc = circuitById(gg, cardData.id);
              if (cc) { delete cc.桌面位置; cc.送审槽 = true; }
            });
          }
        } else if (hitIndex === 'delete') {
          // 删除槽：所有回路均可进（不检查审核状态/种类）；进槽写瞬态标记 待删槽=true，确认后永久移除
          writeGame(function (gg) {
            var fixedLen = FIXED_CAP;
            var src = (cardData.slotIndex !== null && cardData.slotIndex < fixedLen) ? { arr: gg.槽位.固定槽, idx: cardData.slotIndex } : { arr: gg.槽位.自由槽, idx: cardData.slotIndex - fixedLen };
            if (cardData.slotIndex !== null && src.idx >= 0 && src.idx < src.arr.length) src.arr[src.idx] = null;
            var cc = circuitById(gg, cardData.id);
            if (cc) { delete cc.桌面位置; delete cc.送审槽; cc.待删槽 = true; }
          });
        } else if (hitIndex !== -1) {
          // 换槽写回：旧槽清空，新槽占位（战斗中固定槽锁；socket 下标 → 存储下标需减 fixedLen）
          writeGame(function (gg) {
            var fixedLen = FIXED_CAP;
            var tgt = hitIndex < fixedLen ? { arr: gg.槽位.固定槽, idx: hitIndex } : { arr: gg.槽位.自由槽, idx: hitIndex - fixedLen };
            var src = (cardData.slotIndex !== null && cardData.slotIndex < fixedLen) ? { arr: gg.槽位.固定槽, idx: cardData.slotIndex } : { arr: gg.槽位.自由槽, idx: cardData.slotIndex - fixedLen };
            if (gg.主角.战斗中 && tgt.arr === gg.槽位.固定槽) { alert('战斗中固定槽上锁'); return; }
            var ccCheck = circuitById(gg, cardData.id);
            if (ccCheck && !可用(ccCheck)) { alert('该回路未送审通过，不能装配'); return; }
            // 固定槽只接受固化回路（type='fixed'）；自由槽固化/自由均可
            if (tgt.arr === gg.槽位.固定槽 && ccCheck && ccCheck.type !== 'fixed') { alert('固定槽只接受固化回路；自由回路请放入下方自由槽。'); return; }
            if (cardData.slotIndex !== null && src.idx >= 0 && src.idx < src.arr.length) src.arr[src.idx] = null;
            if (tgt.idx >= 0 && tgt.idx < tgt.arr.length) tgt.arr[tgt.idx] = cardData.id;
            var cc = circuitById(gg, cardData.id);
            if (cc) { delete cc.桌面位置; delete cc.送审槽; delete cc.待删槽; }   // 装槽后清自由位置 + 送审/删除槽标记
            cardData.slotIndex = hitIndex;
          });
        } else {
          // 拖到槽位外 → 自由放置（卸槽 + 存桌面位置，卡停在拖放处不消失）
          writeGame(function (gg) {
            var fixedLen = FIXED_CAP;
            var src = (cardData.slotIndex !== null && cardData.slotIndex < fixedLen) ? { arr: gg.槽位.固定槽, idx: cardData.slotIndex } : { arr: gg.槽位.自由槽, idx: cardData.slotIndex - fixedLen };
            if (cardData.slotIndex !== null && src.idx >= 0 && src.idx < src.arr.length) src.arr[src.idx] = null;
            cardData.slotIndex = null;
            var cc = circuitById(gg, cardData.id);
            if (cc) { cc.桌面位置 = { x: Math.round(cardData.x), y: Math.round(cardData.y) }; delete cc.送审槽; delete cc.待删槽; }
          });
        }
        loadFromSave(); renderDesktopCards();
      } else {
        selectCardAndShowDetail(cardData, 'circuit');
      }
    });
  }

  function getOverlappingSocket(cardEl) {
    var r = cardEl.getBoundingClientRect();
    var cx = r.left + r.width / 2, cy = r.top + r.height / 2;
    for (var i = 0; i < slotsContainer.children.length; i++) {
      var sock = document.getElementById('socket_' + i);
      if (!sock) continue;
      var sr = sock.getBoundingClientRect();
      if (cx >= sr.left && cx <= sr.right && cy >= sr.top && cy <= sr.bottom) return i;
    }
    // 送审槽（独立 socket；返回 'review' 哨兵，不与 numeric 槽位索引混淆）
    var revSock = document.getElementById('socket_review');
    if (revSock) {
      var sr2 = revSock.getBoundingClientRect();
      if (cx >= sr2.left && cx <= sr2.right && cy >= sr2.top && cy <= sr2.bottom) return 'review';
    }
    // 删除槽（独立 socket；返回 'delete' 哨兵）
    var delSock = document.getElementById('socket_delete');
    if (delSock) {
      var sd2 = delSock.getBoundingClientRect();
      if (cx >= sd2.left && cx <= sd2.right && cy >= sd2.top && cy <= sd2.bottom) return 'delete';
    }
    return -1;
  }
