        '<div class="dos-banner" style="--dos-acc:' + itemData.accent + '">' + itemData.banner + '</div>' +
        '<div class="dos-specs">' + specsHtml + '</div>' +
        '<div class="dos-lore"><div style="color:#fff;font-weight:700;margin-bottom:6px;">[ 身体代价与实战记录 ]</div><p>' + (itemData.lore || '暂无') + '</p></div>' +
        actionBtn;
      if (isPending) {
        document.getElementById('btnReviewInDetail').addEventListener('click', function () { reviewCircuit(itemData); });
      }
      document.getElementById('btnRecycleInDetail').addEventListener('click', function () { recycleCardFromDetail(itemData); });
    } else if (type === 'affinity') {
