      var tagColor = '#64748b', bannerText = '○ 陌生/高阻抗分支 (不发光)';
      if (itemData.level === 'primary') { levelDesc = '【原生主亲和】：回路完美共振，消耗基线 精神×1 能量×1。'; tagColor = 'var(--acid-green)'; bannerText = '★ 核心主共振分支 (炫彩霓虹流动)'; }
      else if (itemData.level === 'secondary') { levelDesc = '【次亲和倾向】：次级共振，施法精神×2，能量×1.5。'; tagColor = 'var(--acid-orange)'; bannerText = '◐ 次级共振分支 (原本光发散)'; }
      detailContainer.innerHTML =
        '<div class="dos-hero" style="--dos-acc:' + tagColor + '"><div class="dos-cat">' + itemData.familyName + ' · 亲和光谱分支</div><div class="dos-name">' + itemData.name + '</div><div class="dos-energy" style="font-size:18px;color:' + tagColor + '">' + itemData.desc + '</div></div>' +
        '<div class="dos-banner" style="--dos-acc:' + tagColor + '">' + bannerText + '</div>' +
        '<div class="dos-specs"><div style="font-size:10px;color:#64748b;margin-bottom:6px;">施法门控惩罚倍率</div>' +
        '<div class="spec-r"><span class="k">精神力消耗倍率</span><span class="v">' + (itemData.level === 'primary' ? '× 1.0' : itemData.level === 'secondary' ? '× 2.0' : '× 4.0') + '</span></div>' +
        '<div class="spec-r"><span class="k">能量魔素消耗倍率</span><span class="v">' + (itemData.level === 'primary' ? '× 1.0' : itemData.level === 'secondary' ? '× 1.5' : '× 4.0') + '</span></div>' +
        '<div class="spec-r"><span class="k">过载风险加成</span><span class="v">' + (itemData.level === 'none' ? '+15 (高危)' : '+0 (安全)') + '</span></div></div>' +
        '<div class="dos-lore"><div style="color:#fff;font-weight:700;margin-bottom:6px;">[ 人体回路机制剖析 ]</div><p style="margin-bottom:8px;">' + levelDesc + '</p><p>' + itemData.lore + '</p></div>';
    }
  }

  function recycleCardFromDetail(cardData) {
    if (isCombat && cardData.slotIndex !== null && cardData.slotIndex < FIXED_CAP) { alert('战备锁定！战斗中禁止卸载固定回路。'); return; }
    writeGame(function (gg) {
      var fixedLen = FIXED_CAP;
      if (cardData.slotIndex !== null) {
        var src = (cardData.slotIndex < fixedLen) ? { arr: gg.槽位.固定槽, idx: cardData.slotIndex } : { arr: gg.槽位.自由槽, idx: cardData.slotIndex - fixedLen };
        if (src.idx >= 0 && src.idx < src.arr.length) src.arr[src.idx] = null;
      }
      // 关键：自由放置（槽位外）的卡也要清桌面位置，否则点回收没反应、卡仍在桌上
      var cc = circuitById(gg, cardData.id);
      if (cc) { delete cc.桌面位置; delete cc.送审槽; delete cc.待删槽; }   // 送审/删除槽中的卡回收 → 直接回牌库
    });
    selectedEntity = null;
    detailContainer.innerHTML = '<div style="text-align:center;padding:60px 20px;color:#475569;font-size:11px;">[ 回路已成功卸解回库 ]</div>';
    loadFromSave(); renderDesktopCards(); renderRepoList(); switchTab('tabRepo');
  }

  /* ═══════════════════ 待送审回路送审（串行 + 防卡死 + 令牌） ═══════════════════ */
  var isReviewing = false;
  var reviewToken = 0;   // 递增令牌：超时/新请求取代后，丢弃迟到的 AI 响应，防止重复落地

  function 参数模板JSON(famKey) {
    var F = E.FAMS[famKey];
    var 顶层 = [];
    for (var i = 0; i < F.ctrls.length; i++) {
      var ctl = F.ctrls[i];
      顶层.push({ key: ctl.k, label: ctl.label, type: ctl.type, opts: ctl.opts || null, min: ctl.min != null ? ctl.min : null, max: ctl.max != null ? ctl.max : null, def: ctl.def });
    }
    if (famKey !== 'flow') return JSON.stringify({ 族: famKey, 默认参数: E.initParams(famKey), 参数: 顶层 }, null, 1);
    var 子实体 = [];
    for (var j = 0; j < E.SUBKEYS.length; j++) {
      for (var k = 0; k < E.SUBKEYS[j].length; k++) {
        var key = E.SUBKEYS[j][k];
        var s = E.SUBS[key];
        if (!s) continue;
        子实体.push({ key: key, 名称: s.n, 参数: s.ctrls.map(function (c) { return { key: c.k, label: c.label, type: c.type, opts: c.opts || null, min: c.min != null ? c.min : null, max: c.max != null ? c.max : null, def: c.def }; }) });
      }
    }
    return JSON.stringify({ 族: famKey, 说明: 'flow 需先定 mode(作用模态) 与 sub(操纵实体)，再填对应子实体参数', 默认参数: E.initParams(famKey), 顶层参数: 顶层, 子实体参数: 子实体 }, null, 1);
  }

  function 钳制参数(famKey, cIn) {
    var merged = E.syncParams(famKey, cIn || {});
    var 合法键 = {};
    var clamp = function (ctl) {
      合法键[ctl.k] = true;
      if (ctl.type === 'seg') merged[ctl.k] = Math.max(0, Math.min((ctl.opts ? ctl.opts.length : 1) - 1, Math.round(Number(merged[ctl.k]) || 0)));
      else if (ctl.type === 'range') merged[ctl.k] = Math.max(ctl.min || 0, Math.min(ctl.max || 100, Number(merged[ctl.k]) || ctl.def || 0));
    };
    var F = E.FAMS[famKey];
    for (var i = 0; i < F.ctrls.length; i++) clamp(F.ctrls[i]);
    if (famKey === 'flow') {
      var key = E.curKey(merged) || '1-1';
      var subs = (E.SUBS[key] || {}).ctrls || [];
      for (var j = 0; j < subs.length; j++) clamp(subs[j]);
    }
    var out = {};
    for (var kk in merged) if (合法键[kk]) out[kk] = Number(merged[kk]);
    return out;
  }

  function reviewCircuit(cardData) {
    if (isReviewing) { alert('上一次送审尚未完成，请稍候。'); return; }
    var c = circuitById(g, cardData.id);
    if (!c || c.审核状态 !== '待送审') { alert('该回路不处于待送审状态。'); return; }

    isReviewing = true;
    var tok = ++reviewToken;   // 本次送审令牌
    var 模板 = 参数模板JSON(c.famKey);
    var aff = affinityOf(g);
    var fmtAff = function (b) { return (b && b.族 ? b.族 : '') + '·' + (b && b.分支 ? b.分支 : ''); };
    var vars = {
      描述: (c.基线账单 && c.基线账单.一句话效果) ? c.基线账单.一句话效果 : c.名称,
      参数: 模板,
      亲和: '主分支：' + (aff.main.map(fmtAff).join('、') || '无') + '；次分支：' + (aff.subs.map(fmtAff).join('、') || '无'),
      场景: '风力' + g.场景.风力档 + '，无机物' + g.场景.可塑无机物kJ + 'kJ，水体' + (g.场景.水体在场 ? '有' : '无')
    };
    var segs = getSpellPrompt().concat([
      { role: 'user', enabled: true, content: '【剧情获得回路：据"一句话效果"审核物理可行性，并填出该族合理的参数向量】\n{{描述}}\n\n【该族参数模板】\n{{参数}}\n\n【亲和（仅参考）】\n{{亲和}}\n\n【场景】\n{{场景}}\n\n请只输出审核结果 JSON；若通过，规范化回路必须含"参数向量"。' }
    ]);

    // 防卡死：15s 超时兜底（超时 = 失败：清送审槽，牌自动回牌库）
    var deadline = setTimeout(function () {
      if (tok !== reviewToken) return;
      reviewToken++;          // 作废本次响应（迟到响应直接丢弃）
      isReviewing = false;
      alert('送审超时（15s），已放回牌库，请重试。');
      clearReviewDockAndRefresh();
    }, 15000);

    generateRaw({
      ordered_prompts: assembleSpell(segs, vars),
      should_stream: false, should_silence: true,
      generation_id: 'gb_review_' + Date.now(),
      custom_api: getSpellApi(),
      json_schema: { name: 'spell_review', value: { type: 'object', properties: { 结论: { type: 'string', enum: ['通过', '驳回'] }, 规范化回路: { type: ['object', 'null'], properties: { 名称: { type: 'string' }, 一句话效果: { type: 'string' }, 参数向量: { type: 'object' } }, required: ['名称', '一句话效果', '参数向量'], additionalProperties: false }, 解释: { type: ['string', 'null'] } }, required: ['结论', '规范化回路', '解释'], additionalProperties: false } }
    }).then(function (raw) {
      clearTimeout(deadline);
      if (tok !== reviewToken) return;
      isReviewing = false;
      var text = typeof raw === 'string' ? raw : JSON.stringify(raw);
      var m = text.match(/\{[\s\S]*\}/); var json = null;
      try { json = JSON.parse(m ? m[0] : text); } catch (e) {}
      if (json && json.结论 === '通过' && json.规范化回路 && json.规范化回路.参数向量) {
        var params = 钳制参数(c.famKey, json.规范化回路.参数向量);
        var name = String(json.规范化回路.名称 || c.名称).slice(0, 10);
        var effect = String(json.规范化回路.一句话效果 || '');
        writeGame(function (gg) {
          var cc = circuitById(gg, cardData.id);
          if (!cc) return;
          cc.参数向量 = params;
          cc.名称 = name;
          cc.参数明细 = E.readableParams(c.famKey, params);
          cc.分支 = E.branchOf(c.famKey, params);
          if (cc.famKey === 'flow') cc.实体 = String(E.curKey(params));
          cc.审核状态 = '已通过';
          delete cc.送审槽;   // 通过 → 清送审槽 → 牌自动回牌库
          var q = E.quote({ fam: cc.famKey, e: cc.注册e || 0, c: params }, forgeCtx());
          cc.基线账单 = { 输出kJ: q.E_out, 计费kJ: q.bill, 精神: q.mind, 一句话效果: effect || String(q.r.effect || '') };
        });
        loadFromSave(); renderDesktopCards(); renderRepoList(); updateReviewDock();
        openSidebar(); switchTab('tabRepo');
        alert('《' + name + '》送审通过，已填入参数并可用。');
      } else {
        alert('【驳回】' + (json && json.解释 ? json.解释 : '法术AI 未给出可解析结论（请重试）。'));
        clearReviewDockAndRefresh();
      }
    }).catch(function (e) {
      clearTimeout(deadline);
      if (tok !== reviewToken) return;
      isReviewing = false;
      alert('送审失败：' + (e && e.message ? e.message : e));
      clearReviewDockAndRefresh();
    });
  }

  /* 送审完毕（通过/驳回/超时/错误统一）：清送审槽瞬态标记 → 牌自动回牌库并刷新 */
  function clearReviewDockAndRefresh() {
    writeGame(function (gg) {
      gg.回路库.forEach(function (cc) { delete cc.送审槽; });
    });
    loadFromSave(); renderDesktopCards(); renderRepoList(); updateReviewDock();
    openSidebar(); switchTab('tabRepo');
  }

  /* 审核台按钮状态：送审槽有卡才可点；审核中禁用 */
  function updateReviewDock() {
    var btn = btnReviewDock;
    if (!btn) return;
    var dock = g.回路库.find(function (c) { return c.送审槽; });
    if (isReviewing) { btn.disabled = true; btn.textContent = '⟳ 审核中…'; btn.style.opacity = '0.7'; return; }
    if (dock) {
      btn.disabled = false;
      btn.textContent = '⚖ 送审《' + String(dock.名称).slice(0, 8) + '》';
      btn.style.opacity = '1';
    } else {
      btn.disabled = true;
      btn.textContent = '⚖ 送审（送审槽为空）';
      btn.style.opacity = '0.4';
    }
  }
  btnReviewDock.addEventListener('click', function () {
    if (isReviewing) return;
    var dock = g.回路库.find(function (c) { return c.送审槽; });
    if (!dock) { alert('送审槽为空：先把「待送审」回路拖进送审槽。'); return; }
    reviewCircuit(toDeskCard(dock, 'review', null));
  });

  /* ═══════════════════ 销毁台（删除槽）：确认后永久移除回路 ═══════════════════ */
  function updateDeleteDock() {
    var btn = btnDeleteDock;
    if (!btn) return;
    var d = g.回路库.find(function (c) { return c.待删槽; });
    if (d) {
      btn.disabled = false;
      btn.textContent = '✕ 删除《' + String(d.名称).slice(0, 8) + '》';
      btn.style.opacity = '1';
    } else {
      btn.disabled = true;
      btn.textContent = '✕ 删除（删除槽为空）';
      btn.style.opacity = '0.4';
    }
  }
  btnDeleteDock.addEventListener('click', function () {
    var d = g.回路库.find(function (c) { return c.待删槽; });
    if (!d) { alert('删除槽为空：先把要删除的回路拖进删除槽。'); return; }
    if (!confirm('确定要永久销毁回路《' + d.名称 + '》？此操作不可恢复！')) return;
    writeGame(function (gg) {
      gg.回路库 = gg.回路库.filter(function (c) { return c.id !== d.id; });
      // 兜底清槽位引用（正常拖入时已清）
      [gg.槽位.固定槽, gg.槽位.自由槽].forEach(function (arr) {
        for (var i = 0; i < arr.length; i++) if (arr[i] === d.id) arr[i] = null;
      });
    });
    loadFromSave(); renderDesktopCards(); renderRepoList(); renderMonitors(); updatePendingDots();
    alert('《' + d.名称 + '》已永久删除。');
  });

  /* ═══════════════════ 能量/精神补给匣（晶体/导液库存 · 滑杆使用） ═══════════════════ */
  /* 定稿结算公式（同 core/presets.ts 注释，唯一来源在数据侧；此处为面板现算副本）：
     晶体密度 kJ/g：<80 → 1×10^(P/80)；80-99 → 100×10^((P-80)/19)；≥99 → 1e5×10^((P-99)/0.99)
     导液浓度 点/ml：<80 → 0.15+(P/80)×0.35；80-99 → 2+((P-80)/19)×4；≥99 → 100+((P-99)/0.99)×100 */
  function 晶体密度(P) { P = Number(P) || 0; return P < 80 ? 1.0 * Math.pow(10, P / 80) : P < 99 ? 100.0 * Math.pow(10, (P - 80) / 19) : 1e5 * Math.pow(10, (P - 99) / 0.99); }
  function 导液浓度(P) { P = Number(P) || 0; return P < 80 ? 0.15 + (P / 80) * 0.35 : P < 99 ? 2.0 + ((P - 80) / 19) * 4.0 : 100.0 + ((P - 99) / 0.99) * 100.0; }
  /* 旧数据缺省兜底：克数 民用2.0/管控1.0/战略0.05；容量ml 民用30/管控10/战略2 */
  function 克数缺省(P) { P = Number(P) || 0; return P >= 99 ? 0.05 : P >= 80 ? 1.0 : 2.0; }
  function 容量缺省(P) { P = Number(P) || 0; return P >= 99 ? 2 : P >= 80 ? 10 : 30; }
  function 补给总量(kind) {
    var total = 0, parts = [];
    (g.补给物品 || []).forEach(function (s) {
      if (s.名称 !== kind) return;
      var n = s.数量 || 1;
      if (kind === '魔素晶体') {
        var per = n * (s.克数 != null ? s.克数 : 克数缺省(s.纯度)) * 晶体密度(s.纯度);
        parts.push('' + n + '×' + (s.克数 != null ? s.克数 : 克数缺省(s.纯度)) + 'g@' + (s.纯度 != null ? s.纯度 : 0) + '%');
        total += per;
      } else {
        var pm = n * (s.容量ml != null ? s.容量ml : 容量缺省(s.纯度)) * 导液浓度(s.纯度);
        parts.push('' + n + '×' + (s.容量ml != null ? s.容量ml : 容量缺省(s.纯度)) + 'ml@' + (s.纯度 != null ? s.纯度 : 0) + '%');
        total += pm;
      }
    });
    return { total: +(total.toFixed(1)), parts: parts };
  }
  function renderSupplyPanels() {
