  });
  function 消耗补给(kind, pct) {
    var restored = 0;
    writeGame(function (gg) {
      var entries = gg.补给物品.filter(function (s) { return s.名称 === kind; });
      var kindIsC = kind === '魔素晶体';
      var total = 0;
      entries.forEach(function (e) {
        var n = e.数量 || 1;
        total += kindIsC ? n * (e.克数 != null ? e.克数 : 克数缺省(e.纯度)) * 晶体密度(e.纯度) : n * (e.容量ml != null ? e.容量ml : 容量缺省(e.纯度)) * 导液浓度(e.纯度);
      });
      restored = +(total * pct / 100).toFixed(1);
      entries.forEach(function (e) {
        e.数量 = Math.max(0, Math.round((e.数量 || 1) * (1 - pct / 100)));
      });
      gg.补给物品 = gg.补给物品.filter(function (s) { return s.名称 !== kind || s.数量 > 0; });
      if (kindIsC) gg.主角.能量kJ.当前 = Math.min(gg.主角.能量kJ.上限, +(gg.主角.能量kJ.当前 + restored).toFixed(1));
      else gg.主角.精神点.当前 = Math.min(gg.主角.精神点.上限, +(gg.主角.精神点.当前 + restored).toFixed(1));
    });
    return restored;
  }
