  /* ═══════════════════ 补给卡（纯度分级 · 能量/精神/创伤） ═══════════════════ */
  var SUPPLY_CARDS = [];
  var supplyListContainer = $('#supplyListContainer');

  function 补给档位(纯度) {
    var p = (纯度 != null) ? 纯度 : 0;
    if (p >= 99) return '战略';
    if (p >= 80) return '管控';
    return '民用';
  }
  function supplyVisual(s) {
    var eff = s.效果 || {};
    if (eff.目标 === '创伤') {
      var heal = eff.身体状态 === '正常';
      return { tier: '创伤', theme: heal ? '#10b981' : '#f43f5e', effectText: heal ? '伤势 → 正常' : '重伤 → 轻伤' };
    }
    var 档 = 补给档位(s.纯度);
    if (eff.目标 === '能量') {
      var c = 档 === '战略' ? '#f43f5e' : 档 === '管控' ? '#ff6600' : '#00f0ff';
      return { tier: 档, theme: c, effectText: '+' + (eff.增加kJ || 0) + ' kJ' };
    }
    var m = 档 === '战略' ? '#c084fc' : 档 === '管控' ? '#eab308' : '#38bdf8';
    return { tier: 档, theme: m, effectText: '+' + (eff.增加点 || 0) + ' 点' };
  }
  /* uid 区分同一补给的多张牌；旧数据无 uid 时按 名称|纯度 兜底 */
  function supplyKey(s) { return s.uid || (s.名称 + '|' + (s.纯度 != null ? s.纯度 : '')); }
  /* 同名的多张补给，显示编号后缀（取 uid 尾 4 位） */
  function supplyBadge(s) {
    if (s.uid) {
      var tail = String(s.uid).match(/#([^#]*)$/);
      return tail ? '#' + tail[1].slice(-4) : '';
    }
    return '';
  }
  /* 同名补给靠 uid 编号区分：卡面名称尾部挂 #xxxx 徽标（旧数据无 uid 则空） */
  function supplyNameHtml(item) {
    return item.name + (item.badge ? '<span class="sup-uid-n">' + item.badge + '</span>' : '');
  }
  /* 补给图腾 SVG（晶体三档 / 导液安瓿 / 创伤十字 / 神经贴片） */
  function supplyArt(s, v) {
    var eff = s.效果 || {};
    var theme = v.theme;
    if (eff.目标 === '能量') {
      if (v.tier === '战略') return '<svg viewBox="0 0 64 64" width="48" height="48" fill="none" stroke="' + theme + '" stroke-width="1.8"><circle cx="32" cy="32" r="26" stroke-dasharray="3,3" opacity="0.4"/><polygon points="32,4 58,22 48,54 16,54 6,22" fill="rgba(244,63,94,0.2)"/><polygon points="32,14 48,26 42,46 22,46 16,26"/><line x1="32" y1="4" x2="32" y2="14"/><line x1="58" y1="22" x2="48" y2="26"/><line x1="48" y1="54" x2="42" y2="46"/><line x1="16" y1="54" x2="22" y2="46"/><line x1="6" y1="22" x2="16" y2="26"/><circle cx="32" cy="32" r="3" fill="' + theme + '"/></svg>';
      if (v.tier === '管控') return '<svg viewBox="0 0 64 64" width="48" height="48" fill="none" stroke="' + theme + '" stroke-width="1.8"><polygon points="32,6 54,18 54,46 32,58 10,46 10,18" fill="rgba(255,102,0,0.15)"/><line x1="32" y1="6" x2="32" y2="58"/><line x1="10" y1="18" x2="32" y2="30"/><line x1="54" y1="18" x2="32" y2="30"/><line x1="10" y1="46" x2="32" y2="30"/><line x1="54" y1="46" x2="32" y2="30"/></svg>';
      return '<svg viewBox="0 0 64 64" width="48" height="48" fill="none" stroke="' + theme + '" stroke-width="1.6"><polygon points="32,8 50,32 32,56 14,32" fill="rgba(0,240,255,0.1)"/><line x1="14" y1="32" x2="50" y2="32"/><line x1="32" y1="8" x2="32" y2="56"/><polygon points="32,18 42,32 32,46 22,32" stroke-dasharray="2,2"/></svg>';
    }
    if (eff.目标 === '精神') {
      var fillH = v.tier === '战略' ? '88%' : v.tier === '管控' ? '72%' : '55%';
      return '<div style="display:flex;align-items:center;gap:8px;"><div style="width:14px;height:42px;background:rgba(255,255,255,0.04);border:1.5px solid ' + theme + ';border-radius:7px 7px 3px 3px;position:relative;overflow:hidden;box-shadow:0 0 12px ' + theme + ';"><div style="position:absolute;bottom:0;left:0;right:0;height:' + fillH + ';background:linear-gradient(180deg,' + theme + ' 0%,rgba(0,0,0,0.8) 100%);"></div><div style="position:absolute;top:24%;left:0;right:0;height:2px;background:#fff;border-radius:50%;opacity:0.9;"></div></div><div style="font-size:7px;color:#64748b;display:flex;flex-direction:column;gap:6px;"><span>ACTIVE</span><span style="color:' + theme + ';">' + (v.tier === '战略' ? 'CRYO' : v.tier === '管控' ? 'AMP' : 'ORAL') + '</span></div></div>';
    }
    if (eff.身体状态 === '正常') return '<svg viewBox="0 0 64 64" width="46" height="46" fill="none"><circle cx="32" cy="32" r="28" stroke="' + theme + '" stroke-width="2" stroke-dasharray="3,3"/><path d="M26 12 H38 V26 H52 V38 H38 V52 H26 V38 H12 V26 H26 Z" fill="rgba(16,185,129,0.25)" stroke="' + theme + '" stroke-width="2"/></svg>';
    return '<svg viewBox="0 0 70 50" width="48" height="38" fill="none" stroke="' + theme + '" stroke-width="1.8"><rect x="15" y="10" width="40" height="30" rx="3" stroke-dasharray="4,2"/><line x1="5" y1="25" x2="15" y2="25"/><line x1="55" y1="25" x2="65" y2="25"/><circle cx="25" cy="25" r="3" fill="' + theme + '"/><circle cx="35" cy="25" r="3" fill="' + theme + '"/><circle cx="45" cy="25" r="3" fill="' + theme + '"/><path d="M25 25 Q 35 15 45 25" stroke="#fff" stroke-width="1.5"/></svg>';
  }
  function toSupplyCard(s) {
    var v = supplyVisual(s);
    var eff = s.效果 || {};
    var cat = eff.目标 === '能量' ? 'CRYSTAL // 能量' : eff.目标 === '精神' ? 'LIQUID // 精神' : 'TRAUMA // 外科';
    var tierText = eff.目标 === '创伤'
      ? (eff.身体状态 === '正常' ? '急诊常备耗材' : '重伤防断线耗材')
      : (v.tier === '战略' ? '战略级物资' : v.tier === '管控' ? '国家管控物品' : '民用合规流通品');
    var specs = [];
    if (eff.目标 === '能量') specs = [{ k: '储量注入', v: '+' + (eff.增加kJ || 0) + ' kJ' }, { k: '纯度档', v: v.tier }];
    else if (eff.目标 === '精神') specs = [{ k: '精神抚平', v: '+' + (eff.增加点 || 0) + ' 点' }, { k: '纯度档', v: v.tier }];
    else specs = [{ k: '创伤消除', v: eff.身体状态 === '正常' ? '→ 正常稳态' : '重伤 → 轻伤' }, { k: '类别', v: v.tier }];
    var barcode = '<svg class="supply-barcode" viewBox="0 0 70 16" fill="' + v.theme + '"><rect x="0" y="0" width="2" height="16"/><rect x="4" y="0" width="3" height="16"/><rect x="10" y="0" width="1" height="16"/><rect x="13" y="0" width="4" height="16"/><rect x="20" y="0" width="2" height="16"/><rect x="25" y="0" width="5" height="16"/><rect x="33" y="0" width="1" height="16"/><rect x="37" y="0" width="3" height="16"/><rect x="43" y="0" width="4" height="16"/><rect x="50" y="0" width="2" height="16"/><rect x="55" y="0" width="6" height="16"/><rect x="64" y="0" width="3" height="16"/></svg>';
    return {
      key: supplyKey(s),
      name: s.名称,
      纯度: s.纯度,
      数量: s.数量,
      badge: supplyBadge(s),
      tier: v.tier,
      theme: v.theme,
      effectText: v.effectText,
      cat: cat,
      tierText: tierText,
      specs: specs,
      barcode: barcode,
      art: supplyArt(s, v),
      x: (s.桌面位置 && typeof s.桌面位置.x === 'number') ? s.桌面位置.x : 0,
      y: (s.桌面位置 && typeof s.桌面位置.y === 'number') ? s.桌面位置.y : 0,
    };
  }
  function loadSupplies() {
    // 晶体/导液已改为库存型（桌面滑杆补给匣使用），不再以牌的形态出现在桌面/牌库
    SUPPLY_CARDS = (g && g.补给物品 ? g.补给物品.filter(function (s) {
