  }

  function bindSupplyDrag(cardEl, sdata) {
    var down = false, moved = false, sx = 0, sy = 0, ix = 0, iy = 0;
    cardEl.addEventListener('mousedown', function (e) {
      down = true; moved = false; sx = e.clientX; sy = e.clientY; ix = sdata.x; iy = sdata.y;
      e.stopPropagation();
    });
    window.addEventListener('mousemove', function (e) {
      if (!down) return;
      var d = Math.hypot(e.clientX - sx, e.clientY - sy);
      if (d > 6) {
        moved = true;
        cardEl.classList.add('dragging');
        sdata.x = ix + (e.clientX - sx) / zoom1;
        sdata.y = iy + (e.clientY - sy) / zoom1;
        cardEl.style.left = sdata.x + 'px'; cardEl.style.top = sdata.y + 'px';
      }
    });
    window.addEventListener('mouseup', function () {
      if (!down) return;
      down = false; cardEl.classList.remove('dragging');
      if (moved) {
        // 自由移动写回（不进槽位）
        writeGame(function (gg) {
          var sup = gg.补给物品.find(function (x) { return supplyKey(x) === sdata.key; });
          if (sup) sup.桌面位置 = { x: Math.round(sdata.x), y: Math.round(sdata.y) };
        });
        loadFromSave(); renderDesktopSupplyCards(); renderSupplyList();
      } else {
        selectSupplyDetail(sdata);
      }
    });
  }

  function selectSupplyDetail(sdata) {
    selectedEntity = sdata;
    openSidebar(); switchTab('tabDetail');
    detailContainer.innerHTML =
      '<div class="dos-hero" style="--dos-acc:' + sdata.theme + '"><div class="dos-cat">SUPPLY // ' + sdata.tier + (sdata.纯度 != null ? ' · ' + sdata.纯度 + '%' : '') + '</div><div class="dos-name">' + supplyNameHtml(sdata) + '</div><div class="dos-energy">' + sdata.effectText + '</div></div>' +
      '<div class="dos-banner" style="--dos-acc:' + sdata.theme + '">' + (sdata.数量 > 1 ? '数量 ×' + sdata.数量 : '单件 · 一牌一件' + (sdata.badge ? ' · ' + sdata.badge : '')) + '</div>' +
      '<div class="dos-specs">' +
      '<div class="spec-r"><span class="k">类别</span><span class="v">' + sdata.tier + '</span></div>' +
      '<div class="spec-r"><span class="k">效果</span><span class="v">' + sdata.effectText + '</span></div>' +
      (sdata.纯度 != null ? '<div class="spec-r"><span class="k">纯度</span><span class="v">' + sdata.纯度 + '%</span></div>' : '') +
      '</div>' +
      '<div style="display:flex;gap:8px;margin-top:10px;">' +
      '<button class="btn-recycle-card" id="btnUseSupply" style="border-color:var(--acid-green);color:var(--acid-green);flex:1;">▸ 使用此补给</button>' +
      '<button class="btn-recycle-card" id="btnRecycleSupply" style="flex:1;">⇲ 回收（放回补给库）</button>' +
      '</div>';
    document.getElementById('btnUseSupply').addEventListener('click', function () { useSupply(sdata); });
    document.getElementById('btnRecycleSupply').addEventListener('click', function () { recycleSupply(sdata); });
  }

  function recycleSupply(sdata) {
    writeGame(function (gg) {
      var sup = gg.补给物品.find(function (x) { return supplyKey(x) === sdata.key; });
      if (sup) delete sup.桌面位置;
    });
    selectedEntity = null;
    detailContainer.innerHTML = '<div style="text-align:center;padding:60px 20px;color:#475569;font-size:11px;">[ 补给已收回补给品库 ]</div>';
    loadFromSave(); renderDesktopSupplyCards(); renderSupplyList(); switchTab('tabSupply');
  }

  function useSupply(sdata) {
    writeGame(function (gg) {
      var sup = gg.补给物品.find(function (x) { return supplyKey(x) === sdata.key; });
      if (!sup || sup.数量 <= 0) { alert('补给不存在或已耗尽'); return; }
      var supTitle = sup.名称 + (sup.uid ? ' ' + supplyBadge(sup) : '');
      var eff = sup.效果 || {};
      if (eff.目标 === '能量') {
        gg.主角.能量kJ.当前 = Math.min(gg.主角.能量kJ.上限, gg.主角.能量kJ.当前 + (eff.增加kJ || 0));
        alert('使用《' + supTitle + '》：能量 +' + (eff.增加kJ || 0) + ' kJ');
      } else if (eff.目标 === '精神') {
        gg.主角.精神点.当前 = Math.min(gg.主角.精神点.上限, gg.主角.精神点.当前 + (eff.增加点 || 0));
        alert('使用《' + supTitle + '》：精神 +' + (eff.增加点 || 0) + ' 点');
      } else {
        var 顺序 = ['正常', '轻伤', '重伤', '过载透支'];
        var 当前 = 顺序.indexOf(gg.主角.身体状态);
        var 目标 = 顺序.indexOf(eff.身体状态 || '正常');
        if (目标 < 当前) { alert('使用《' + supTitle + '》：身体 ' + gg.主角.身体状态 + ' → ' + eff.身体状态); gg.主角.身体状态 = eff.身体状态 || '正常'; }
        else { alert('《' + supTitle + '》伤势不重于此档，无效'); return; }
      }
      sup.数量 -= 1;
      if (sup.数量 <= 0) gg.补给物品 = gg.补给物品.filter(function (x) { return x !== sup; });
    });
    loadFromSave(); renderDesktopSupplyCards(); renderSupplyList(); renderMonitors();
    detailContainer.innerHTML = '<div style="text-align:center;padding:60px 20px;color:#475569;font-size:11px;">[ 补给已使用 ]</div>';
  }

  /* ═══════════════════ 桌面3：自由施法桌（临时回路构筑） ═══════════════════ */
  var forgeTuningRack = $('#forgeTuningRack');
  var rackTitle = $('#rackTitle');
  var rackSub = $('#rackSub');
  var rackEnergySliderWrap = $('#rackEnergySliderWrap');
  var rackControlsList = $('#rackControlsList');
  var inputE = $('#inputE');
  var sliderEVal = $('#sliderEVal');
  var chkUnlockE = $('#chkUnlockE');

  /* 限制解除：解除后能量滑杆上限 = max(500, 主角能量上限)；低于500保持不变 */
  var unlockE = false;
  function updateEnergyCap() {
    var maxKJ = 500;
    if (unlockE && g && g.主角 && g.主角.能量kJ && g.主角.能量kJ.上限) {
      maxKJ = Math.max(500, g.主角.能量kJ.上限);
    }
    var newMax = Math.max(100, E.kjToSlider(maxKJ) + 1);
    inputE.max = newMax;
    if (parseInt(inputE.value, 10) > newMax) {
      inputE.value = newMax;
      FORGE_STATE.e = newMax;
      sliderEVal.textContent = E.sliderToKJ(FORGE_STATE.e).toFixed(1) + ' kJ';
      recalcForgeQuote();
    }
  }
  chkUnlockE.addEventListener('change', function () {
    unlockE = chkUnlockE.checked;
    updateEnergyCap();
  });
  var teleOutputNum = $('#teleOutputNum');
  var teleOutputAnchor = $('#teleOutputAnchor');
  var teleBillVal = $('#teleBillVal');
  var teleMindVal = $('#teleMindVal');
  var teleTimeVal = $('#teleTimeVal');
  var teleRiskVal = $('#teleRiskVal');
  var teleTellLv = $('#teleTellLv');
  var gateBadge = $('#gateBadge');
  var tunedAlertBox = $('#tunedAlertBox');
  var tunedCircuitName = $('#tunedCircuitName');
  var chipsFlow = $('#chipsFlow');
  var intentDesc = $('#intentDesc');

  var famColors = { pour: '#00f0ff', flow: '#c6ff00', struct: '#ff6600', life: '#f43f5e', perce: '#eab308' };

  /* 构筑台上下文：真实存档 + 已装槽固定回路（微调命中用） */
  function forgeCtx() {
    return {
      aff: affinityOf(g),
      scene: { wind: g.场景.风力档, mat: g.场景.可塑无机物kJ, water: g.场景.水体在场 },
      char: { burstKW: g.主角.爆发线kW, sustainKW: g.主角.持续线kW, speed: 1, eCur: g.主角.能量kJ.当前, mCur: g.主角.精神点.当前, mMax: g.主角.精神点.上限, body: g.主角.身体状态 },
      tuned: tunedList(g)
    };
  }

  function renderForgeControls() {
    var fam = FORGE_STATE.fam;
    var F = E.FAMS[fam];
    var curColor = famColors[fam] || '#c6ff00';
    forgeTuningRack.style.setProperty('--cur-fam-color', curColor);
    rackTitle.textContent = F.name + ' // 参数调制插槽';
    rackSub.textContent = F.sub;
    rackEnergySliderWrap.style.display = fam === 'flow' ? 'none' : 'block';
    rackControlsList.innerHTML = '';
    var allCtrls = F.ctrls.slice();
    if (fam === 'flow') {
      var subObj = E.SUBS[E.curKey(FORGE_STATE.c)];
      if (subObj && subObj.ctrls) allCtrls = allCtrls.concat(subObj.ctrls);
    }
    allCtrls.forEach(function (ctl) {
      if (ctl.show && !ctl.show(FORGE_STATE.c)) return;
      var itemDiv = document.createElement('div');
      itemDiv.className = 'ctrl-item';
      if (ctl.type === 'seg') {
        var opts = ctl.opts;
        if (ctl.k === 'sub') {
          var modeIdx = FORGE_STATE.c.mode || 0;
          opts = E.SUBKEYS[modeIdx].map(function (k) { return E.SUBS[k].n.split(' ')[0]; });
        }
        var btnGroup = document.createElement('div');
        btnGroup.className = 'seg-btn-group';
        opts.forEach(function (optText, optIdx) {
          var btn = document.createElement('div');
          btn.className = 'seg-opt-btn' + (FORGE_STATE.c[ctl.k] === optIdx ? ' active' : '');
          btn.textContent = optText;
          btn.addEventListener('click', function () {
            FORGE_STATE.c[ctl.k] = optIdx;
            FORGE_STATE.c = E.syncParams(FORGE_STATE.fam, FORGE_STATE.c);
            FORGE_STATE.preset = null;   // 手动改参数后不再是预设
            renderForgeControls();
            recalcForgeQuote();
          });
          btnGroup.appendChild(btn);
        });
        itemDiv.innerHTML = '<div class="ctrl-label-row"><span class="lbl">' + ctl.label + '</span></div>';
        itemDiv.appendChild(btnGroup);
      } else if (ctl.type === 'range') {
        var curVal = FORGE_STATE.c[ctl.k];
        var fmtStr = ctl.fmt ? ctl.fmt(curVal) : curVal;
        itemDiv.innerHTML =
          '<div class="ctrl-label-row"><span class="lbl">' + ctl.label + '</span><span class="val" id="lbl_' + ctl.k + '">' + fmtStr + '</span></div>' +
          '<input type="range" class="acid-slider" min="' + ctl.min + '" max="' + ctl.max + '" step="' + ctl.step + '" value="' + curVal + '">';
        var slider = itemDiv.querySelector('input');
        slider.addEventListener('input', function (e2) {
          var val = parseFloat(e2.target.value);
          FORGE_STATE.c[ctl.k] = val;
          FORGE_STATE.preset = null;   // 手动改参数后不再是预设
          var lbl = itemDiv.querySelector('#lbl_' + ctl.k);
          if (lbl) lbl.textContent = ctl.fmt ? ctl.fmt(val) : val;
          recalcForgeQuote();
        });
      }
      rackControlsList.appendChild(itemDiv);
    });
  }

  function recalcForgeQuote() {
    var q = E.quote({ fam: FORGE_STATE.fam, e: FORGE_STATE.e, c: FORGE_STATE.c }, forgeCtx());
    teleOutputNum.innerHTML = q.E_out.toFixed(q.E_out < 10 ? 2 : 1) + '<span style="font-size:14px; margin-left:4px; color:var(--acid-green);">kJ</span>';
    teleOutputAnchor.textContent = E.anchorOf(q.E_out);
    teleBillVal.textContent = q.bill + ' kJ';
    teleMindVal.textContent = q.mind + ' 点';
    teleTimeVal.textContent = q.relT.toFixed(2) + ' s';
    teleRiskVal.textContent = q.risk + ' %';
    teleTellLv.textContent = q.tell;
    gateBadge.className = 'gate-badge ' + q.r.g.t;
    gateBadge.textContent = q.r.branch + ' · ' + q.r.g.n;
    if (q.tunedHit) { tunedAlertBox.classList.add('active'); tunedCircuitName.textContent = q.tunedName || q.tunedHit; }
    else { tunedAlertBox.classList.remove('active'); }
    chipsFlow.innerHTML = '';
    (q.chips || []).forEach(function (chip) {
      var line = document.createElement('div');
      line.className = 'chip-line ' + (chip.l || 'y');
      line.textContent = '• ' + chip.t;
      chipsFlow.appendChild(line);
    });
    return q;
  }

  document.querySelectorAll('.fam-switch-item').forEach(function (item) {
    item.addEventListener('click', function () {
      document.querySelectorAll('.fam-switch-item').forEach(function (i) { i.classList.remove('active'); });
      item.classList.add('active');
      FORGE_STATE.fam = item.dataset.fam;
      FORGE_STATE.c = E.initParams(FORGE_STATE.fam);
      FORGE_STATE.preset = null;   // 手动切族后不再是预设
      renderForgeControls();
      recalcForgeQuote();
    });
  });
  inputE.addEventListener('input', function (e2) {
    FORGE_STATE.e = parseInt(e2.target.value, 10);
    FORGE_STATE.preset = null;   // 手动调能量后不再是预设
    sliderEVal.textContent = E.sliderToKJ(FORGE_STATE.e).toFixed(1) + ' kJ';
    recalcForgeQuote();
  });

  function nextFreeId(g2) {
    var n = 1, ids = (g2.回路库 || []).map(function (c) { return c.id; });
    while (ids.indexOf('fr-' + (n < 10 ? '0' + n : n)) >= 0) n++;
    return 'fr-' + (n < 10 ? '0' + n : n);
  }

  /* ═══════════════════ 法术AI 送审（玩家自创回路必须先送审通过才能用） ═══════════════════ */
  function getSpellPrompt() {
    try {
      var st = (typeof SillyTavern !== 'undefined') && SillyTavern.getContext && SillyTavern.getContext();
      var seg = st && st.extensionSettings && st.extensionSettings['渐变带自由回路'] && st.extensionSettings['渐变带自由回路'].提示词 && st.extensionSettings['渐变带自由回路'].提示词.法术AI;
      if (seg && seg.length) return seg;
    } catch (e) {}
    return [
      { role: 'system', enabled: true, content: '你是跑团系统的"法术AI"，负责审核施法回路是否合理（物理可行性，与亲和无关；不做账单计算）。双场景：自创申报（{{参数}}为中文参数明细）通过时规范化回路输出 {"名称","一句话效果","效果文字稿"}；剧情获得送审（{{参数}}为参数模板JSON）通过时必须含"参数向量"。输出二选一 JSON：通过→{"结论":"通过","规范化回路":{…}}；驳回→{"结论":"驳回","解释":"通俗说明"}。只输出 JSON。' },
      { role: 'user', enabled: true, content: '【玩家描述】\n{{描述}}\n\n【构筑参数】\n{{参数}}\n\n【场景】\n{{场景}}\n\n【亲和（仅参考）】\n{{亲和}}\n\n请输出审核结果 JSON。' }
    ];
  }
  function getSpellApi() {
    try {
      var st = (typeof SillyTavern !== 'undefined') && SillyTavern.getContext && SillyTavern.getContext();
      var cfg = st && st.extensionSettings && st.extensionSettings['渐变带自由回路'] && st.extensionSettings['渐变带自由回路'].api;
      return cfg && cfg.法术AI && cfg.法术AI.mode === 'custom' ? cfg.法术AI : undefined;
    } catch (e) { return undefined; }
  }
  function assembleSpell(segs, vars) {
    return segs.filter(function (s) { return s.enabled !== false; }).map(function (s) {
      var c = s.content;
      Object.keys(vars).forEach(function (k) { c = c.split('{{' + k + '}}').join(vars[k]); });
      return { role: s.role, content: c };
    });
  }

  /* 出口 A：申报入自由库（预设回路免审直接入库；自定义送审 → 通过才入库） */
  $('#btnSaveToRepo').addEventListener('click', function () {
    if (!g) { alert('尚未开局'); return; }

    // 预设回路：直接免审入库（系统内置完整参数，不送审）
    if (FORGE_STATE.preset) {
      var p = FORGE_STATE.preset;
      var params0 = E.syncParams(p.fam, FORGE_STATE.c);
      writeGame(function (gg) {
        var qq = E.quote({ fam: p.fam, e: p.e, c: params0 }, forgeCtx());
        gg.回路库.push({
          id: nextFreeId(gg), 名称: p.name, type: 'free',
          族: E.FAMKEY[p.fam], famKey: p.fam,
          分支: E.branchOf(p.fam, params0),
          实体: p.fam === 'flow' ? String(E.curKey(params0)) : null,
          参数向量: params0, 注册e: p.fam === 'flow' ? 0 : p.e,
          参数明细: E.readableParams(p.fam, params0),
          微调预算: null, 微调预算明细: null,
          基线账单: { 输出kJ: qq.E_out, 计费kJ: qq.bill, 精神: qq.mind, 一句话效果: p.effect },
          uses: 0, 来源: '开局预设',
          审核存档: null, 审核状态: '免审'
        });
      });
      loadFromSave(); renderDesktopCards(); renderRepoList();
      openSidebar(); switchTab('tabRepo');
      alert('预设回路《' + p.name + '》已入自由库（免审）。');
      return;
    }

    var desc = intentDesc.value.trim();
    if (desc.length < 8) { alert('构筑意图描述太短：至少写清"作用对象 + 作用方式"（≥8字）。'); return; }
    var q = recalcForgeQuote();
    var params = E.syncParams(FORGE_STATE.fam, FORGE_STATE.c);

    var aff = affinityOf(g);
    var fmtAff = function (b) { return (b && b.族 ? b.族 : '') + '·' + (b && b.分支 ? b.分支 : ''); };
    var vars = {
      描述: desc,
      参数: JSON.stringify({ 族: FORGE_STATE.fam, 参数明细: E.readableParams(FORGE_STATE.fam, params), 引擎参考效果: String(q.r.effect || '') }, null, 1),
      亲和: '主分支：' + (aff.main.map(fmtAff).join('、') || '无') + '；次分支：' + (aff.subs.map(fmtAff).join('、') || '无'),
      场景: '风力' + g.场景.风力档 + '，无机物' + g.场景.可塑无机物kJ + 'kJ，水体' + (g.场景.水体在场 ? '有' : '无')
    };

    generateRaw({
      ordered_prompts: assembleSpell(getSpellPrompt(), vars),
      should_stream: false, should_silence: true,
      generation_id: 'gb_spell_desk_' + Date.now(),
      custom_api: getSpellApi(),
      json_schema: { name: 'spell_review', value: { type: 'object', properties: { 结论: { type: 'string', enum: ['通过', '驳回'] }, 规范化回路: { type: ['object', 'null'], properties: { 名称: { type: 'string' }, 一句话效果: { type: 'string' }, 效果文字稿: { type: 'string' } }, required: ['名称', '一句话效果'], additionalProperties: false }, 解释: { type: ['string', 'null'] } }, required: ['结论', '规范化回路', '解释'], additionalProperties: false } }
    }).then(function (raw) {
      var text = typeof raw === 'string' ? raw : JSON.stringify(raw);
      var m = text.match(/\{[\s\S]*\}/); var json = null;
      try { json = JSON.parse(m ? m[0] : text); } catch (e) {}
      if (json && json.结论 === '通过' && json.规范化回路) {
        var name = String(json.规范化回路.名称 || desc.slice(0, 7) + '·自创').slice(0, 10);
        var effect = String(json.规范化回路.一句话效果 || q.r.effect || '');
        writeGame(function (gg) {
          var qq = E.quote({ fam: FORGE_STATE.fam, e: FORGE_STATE.e, c: params }, forgeCtx());
          gg.回路库.push({
            id: nextFreeId(gg), 名称: name, type: 'free',
            族: E.FAMKEY[FORGE_STATE.fam], famKey: FORGE_STATE.fam,
            分支: E.branchOf(FORGE_STATE.fam, params),
            实体: FORGE_STATE.fam === 'flow' ? String(E.curKey(params)) : null,
            参数向量: params, 注册e: FORGE_STATE.fam === 'flow' ? 0 : FORGE_STATE.e,
            参数明细: E.readableParams(FORGE_STATE.fam, params),
            微调预算: null, 微调预算明细: null,
            基线账单: { 输出kJ: qq.E_out, 计费kJ: qq.bill, 精神: qq.mind, 一句话效果: effect },
            uses: 0, 来源: '面板送审',
            审核存档: { 原始描述: desc, 规范化结果: json.规范化回路 },
            审核状态: '已通过'
          });
        });
        loadFromSave(); renderDesktopCards(); renderRepoList();
        openSidebar(); switchTab('tabRepo');
        alert('自由回路《' + name + '》送审通过，已入自由库（一句话效果：' + effect + '）。');
      } else {
        alert('【驳回】' + (json && json.解释 ? json.解释 : '法术AI 未给出可解析结论（请重试或改描述）。'));
      }
    }).catch(function (e) {
      alert('送审失败（法术AI 不可用）：' + (e && e.message ? e.message : e));
    });
  });

  /* 出口 B（临时强冲）已按用户要求移除：自由施法桌只保留「申报入自由库」 */

  /* ═══════════════════ 桌面切换 / 缩放平移 / 战备 ═══════════════════ */
  function switchDesk(n) {
    $('#btnNavDesk1').classList.toggle('active', n === 1);
    $('#btnNavDesk2').classList.toggle('active', n === 2);
    $('#btnNavDesk3').classList.toggle('active', n === 3);
    $('#viewportDesk1').classList.toggle('active', n === 1);
    $('#viewportDesk2').classList.toggle('active', n === 2);
    $('#viewportDesk3').classList.toggle('active', n === 3);
    if (n === 2) { renderActorBanner(); renderAffinityBoard(); }
    if (n === 3) { renderForgeControls(); recalcForgeQuote(); }
  }
  $('#btnNavDesk1').addEventListener('click', function () { switchDesk(1); });
  $('#btnNavDesk2').addEventListener('click', function () { switchDesk(2); });
  $('#btnNavDesk3').addEventListener('click', function () { switchDesk(3); });

  /* 缩放档位（固定 6 档 · zoom 重排 → 全档清晰）；平移按 zoom 折算；桌面 rotateX 倾斜，卡片反旋正视 */
  var ZOOM_LEVELS = [0.5, 0.8, 1.0, 1.3, 1.6, 2.0];
  function stepZoom(cur, dir) {
    var i = ZOOM_LEVELS.indexOf(cur); if (i < 0) i = 2;
    i = Math.max(0, Math.min(ZOOM_LEVELS.length - 1, i + dir));
    return ZOOM_LEVELS[i];
  }

  var zoom1 = 1.0, panX1 = 0, panY1 = 0, isPanning1 = false, startX1 = 0, startY1 = 0, origPX1 = 0, origPY1 = 0;
  function upd1() {
    surfaceDesk1.style.zoom = zoom1;
    surfaceDesk1.style.transform = 'translate(calc(-50% + ' + panX1 + 'px), calc(-50% + ' + panY1 + 'px))';
  }
  $('#viewportDesk1').addEventListener('wheel', function (e) { e.preventDefault(); zoom1 = stepZoom(zoom1, e.deltaY < 0 ? 1 : -1); upd1(); }, { passive: false });
  $('#viewportDesk1').addEventListener('mousedown', function (e) {
    if (e.target === $('#viewportDesk1') || e.target === surfaceDesk1 || e.target.classList.contains('slot-matrix-grid')) {
      isPanning1 = true; $('#viewportDesk1').classList.add('grabbing');
      startX1 = e.clientX; startY1 = e.clientY; origPX1 = panX1; origPY1 = panY1;
    }
  });
  window.addEventListener('mousemove', function (e) {
    if (isPanning1) {
      panX1 = Math.max(-1200, Math.min(1200, origPX1 + (e.clientX - startX1) / zoom1));
      panY1 = Math.max(-900, Math.min(900, origPY1 + (e.clientY - startY1) / zoom1));
      upd1();
    }
  });
  window.addEventListener('mouseup', function () { isPanning1 = false; $('#viewportDesk1').classList.remove('grabbing'); });

  var surfaceDesk2 = $('#surfaceDesk2');
  var zoom2 = 1.0, panX2 = 0, panY2 = 0, isPanning2 = false, startX2 = 0, startY2 = 0, origPX2 = 0, origPY2 = 0;
  function upd2() {
    surfaceDesk2.style.zoom = zoom2;
    surfaceDesk2.style.transform = 'translate(calc(-50% + ' + panX2 + 'px), calc(-50% + ' + panY2 + 'px))';
  }
  $('#viewportDesk2').addEventListener('wheel', function (e) { e.preventDefault(); zoom2 = stepZoom(zoom2, e.deltaY < 0 ? 1 : -1); upd2(); }, { passive: false });
  $('#viewportDesk2').addEventListener('mousedown', function (e) {
